          :label="$t('table_extraction_view')"
          color="primary"
          :to="'/tbl_ext_v3/' + docStore.record.doc_id"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <!-- END restrict PO Edit If Not Validated -->

  <!-- Block Columns List -->
  <q-dialog v-model="openDisableColumnListView">
    <q-card style="min-width: 700px; width: 700px; max-width: 50vw">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">{{
            $t('diabled_custom_columns')
          }}</span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>
      <BlockedColumns :rows="disableColumnList"></BlockedColumns>
    </q-card>
  </q-dialog>
  <!-- END Block Columns List -->

  <!-- Revert changes Confirmation -->
  <q-dialog v-model="revert_changes_confirm_dialog" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section
        tag="span"
        class="row items-center"
        style="justify-content: center; display: flex"
      >
        <span class="q-ml-sm">{{ $t('revert_changes_confirm') }}</span>
        <span class="q-ml-sm">{{ $t('revert_changes_confirm_2') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          appearance="cancel"
          :label="$t('cancel')"
          v-close-popup
          @click="revert_changes_confirm_dialog = false"
        />
        <f-btn
          :label="$t('proceed')"
          class="q-mr-sm"
          @click="revertChanges(true)"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <ManageRuleRegexes
    :showRegexDlg="showRegexDlg"
    @setShowRegexDlg="setShowRegexDlg"
    @updateRegexByRule="updateRegexByRule"
  />
</template>

<script lang="ts">

import axios from 'axios';
import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import { type dynamicObj, $ } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import documentUtil from 'src/utils/documentUtil';
import { SessionStorage } from 'quasar';
import { ApiExceptions } from 'src/exceptions/index';
import ColorGenerator from 'src/utils/ColorGenerator';
import { api, getAuthorizationToken } from 'pages/APIs';
import resizableGridUtil from 'src/utils/resizableGridUtil';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { isRegexPatternValid } from 'src/utils/validateRegex';
import BlockedColumns from 'src/components/BlockedColumns.vue';
import { rowRgbaColor, rowRgbaColorStr } from 'src/constants';
import { useDocumentStore, useLineItemStore } from 'src/store/main';
import ManageRuleRegexes from 'src/components/ManageRuleRegexes.vue';
import amountConversionHelper from 'src/utils/amountConversionHelper';
import { isObjectEmtpy, isUndefinedOrNull, isObject } from 'src/utils/general';
import CreateCustomColumn from 'src/pages/Settings/customColumns/Create-Custom-Column.vue';
import { storeToRefs } from 'pinia';
import ColumnOrigin from 'src/formBuilder/form_elements/components/ExtractedTableTabPanels/ColumnOrigin.vue';
import ExtractOrigin from 'src/formBuilder/form_elements/components/ExtractedTableTabPanels/ExtractOrigin.vue';
import docTablesUtil from 'src/utils/docTablesUtil';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { notify } from 'src/components/notifications/notify';
import { Acl, FieldPermission } from 'src/core/acls/Acl';

export interface synonymType {
  techName: string;
  label: string;
}
let selectedElement: any;
// this Map conatins which column is completly empty and which column has atleast one record
let columnDataStatusMap = new Map();

export default defineComponent({
  el: '#app',
  mixins: [docTablesUtil,
    helperMixin,
    ColorGenerator,
    resizableGridUtil,
    documentUtil,
    helperUtil,
    amountConversionHelper,
    displayFieldLabel],
  props: {
    apiDataProp: {} as any,
    extractedData: {
      type: String,
      default: '',
    },
    currentPageNo: {
      type: Number,
      default: 1,
    },
    isRowMode: {
      type: Boolean,
      default: false,
    },
    training_mode: {
      type: Boolean,
      default: false,
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  emits: [
    'updateExtractionDataForSave',
    'setTableRowCorrdinates',
    'loadNewPageImage',
  ],
  components: {
    
    BlockedColumns,
    ManageRuleRegexes,
    CreateCustomColumn,
    ColumnOrigin,
    ExtractOrigin,
  },
  data() {
    return {
      docId: '',
      dropdownColumns: [] as any,
      rows_to_delete: [] as any,
      po_dragging: false,
      dragging_data: {} as any,
      coveredLineItem: [] as any,
      validation_done: true,
      connected_line_item: '',
      confirmDialog: ref(false),
      renderKey: 0,
      is_po_view: false,
      selectedColumn: ref(''),
      showRegexDlg: ref(false),
      openAdvSettings: ref(false),
      oldSelectedColumnName: ref(''),
      po_connected_line_items: {} as { [k: string]: any },
      is_auto_filled_color: '#c2dba6',
      is_missing_color: '#eed69e',
      tableId: 'line_item_table',
    };
  },
  mounted: function () {
    document.addEventListener('revert_changes', () => {
      this.revertChanges().then();
    });
    document.addEventListener('add_new_row', this.createRowJson);
    document.addEventListener('add_new_column', this.addNewCustomColumn);
    document.addEventListener('reset_line_items', this.resetlintItems);
    document.addEventListener('init_line_items', this.lineItemDataLoaded);
    document.addEventListener('reload_line_items', this.reloadLineItemData);
    document.addEventListener('get_table_rows_areas', this.getTableRowsAreas);
    document.addEventListener(
      'display_adv_settings_view',
      this.openAdvanceSettings,
    );
    document.addEventListener(
      'open_disabled_custom_columns_view',
      this.openDisabledCstmColumnsView,
    );
    document.addEventListener('enable_custom_column', this.enableCustomColumn);
    document.addEventListener('custom_column_create', this.customColumnCreated);
    document.addEventListener('display_fields_errors', this.displayFieldErrors);

     
    document.addEventListener('restore_delete_column', async (event: any) => {
      await this.restoreDeleteColumn(event);
    });

    this.isViewPo();
    (<any>window).lineItemsV3 = this;
  },
  unmounted: function () {
    document.removeEventListener('revert_changes', () => {
      this.revertChanges().then();
    });
    document.removeEventListener('add_new_row', this.createRowJson);
    document.removeEventListener('add_new_column', this.addNewCustomColumn);
    document.removeEventListener('reset_line_items', this.resetlintItems);
    document.removeEventListener('init_line_items', this.lineItemDataLoaded);
    document.removeEventListener('reload_line_items', this.reloadLineItemData);
    document.removeEventListener(
      'get_table_rows_areas',
      this.getTableRowsAreas,
    );
    document.removeEventListener(
      'display_adv_settings_view',
      this.openAdvanceSettings,
    );
    document.removeEventListener(
      'open_disabled_custom_columns_view',
      this.openDisabledCstmColumnsView,
    );
    document.removeEventListener(
      'enable_custom_column',
      this.enableCustomColumn,
    );
    document.removeEventListener(
      'custom_column_create',
      this.customColumnCreated,
    );
    document.removeEventListener(
      'display_fields_errors',
      this.displayFieldErrors,
    );

     
    document.removeEventListener(
      'restore_delete_column',
      async (event: any) => {
        await this.restoreDeleteColumn(event);
      },
    );
  },
  watch: {
    extractedData(val) {
      selectedElement.value = val;
      (selectedElement.parentElement as HTMLElement).classList.remove('active');
      selectedElement = null;
    },
    currentPageNo(val) {
      this.highliteFirstRowOfCurrentPage();
    },
  },
  methods: {
    addExtractionMethodClass(column: any) {
      let extraction_class = '';
      if (
        column &&
        column.hasOwnProperty('extraction_method') &&
        column.extraction_method !== ''
      ) {
        extraction_class = 'extraction_method';
      }

      return extraction_class;
    },
    reloadLineItemData(e: any) {
      if (!e || !e.detail) {
        return;
      }

      this.lineItemsloading = false;
      let data = e.detail.apiData;
      this.resetRows();
      this.docStore.record = data;
      this.docId =
        this.docStore.record && this.docStore.record.doc_id
          ? this.docStore.record.doc_id
          : '';
      this.refactorApiData();
      let detailObj = {
        rowId: e.detail.currentRowId,
        columnName: e.detail.currentColumnName,
        onlySelectedRow: true,
      };
      this.getTableRowsAreas({ detail: detailObj });

      setTimeout(() => {
        const event = new CustomEvent('enable_column_selection', {
          detail: e.detail.currentRowId,
        });
        document.dispatchEvent(event);
      }, 10);
    },
    lineItemDataLoaded(e: any) {
      if (!e || !e.detail) {
        return;
      }

      this.lineItemsloading = false;
      let data = e.detail;
      this.resetRows();
      this.docStore.record = data;
      this.docId =
        this.docStore.record && this.docStore.record.doc_id
          ? this.docStore.record.doc_id
          : '';
      this.refactorApiData();
    },
    isViewEditable() {
      if (this.is_po_view) {
        return false;
      }
      if (!this.training_mode) {
        notify.error('Please select training mode');
        return false;
      }
      return true;
    },
    async getToken() {
      let token: string =
        this.docStore.record.token &&
        this.docStore.record.token != null &&
        this.docStore.record.token != ''
          ? this.docStore.record.token
          : await getAuthorizationToken();
      return token;
    },
    async groupByColumn(index: string) {
      if (index === '' || index == undefined || index == null) {
        return;
      }
      this.group_column = index;
      await this.requestReformate();
    },
    getColumnMappingIndexes() {
      let column_mapping_indexes: { [k: string]: any } = {};
      for (const name in this.column_mapping_indexes) {
        let keyIndex = this.column_mapping_indexes[name];
        column_mapping_indexes[name] = keyIndex;
      }

      return column_mapping_indexes;
    },
    async resetFormating() {
      this.group_column = '';
      await this.requestReformate();
    },
    validateLineItemColumns() {
      let hasError = false;
      this.docStore.record['table_has_error'] = false;

      if (this.tableColumns === undefined) {
        return;
      }
      let missing_mapping_columns = [] as string[];
      for (const column of this.tableColumns) {
        let isValid = this.isColumnNameValid(column);
        if (!isValid) {
          this.docStore.record['table_has_error'] = true;
          column.error = true;
          hasError = true;
          missing_mapping_columns.push(column.name);
          continue;
        }
      }

      let newValidation = !hasError;
      this.is_line_item_validated = newValidation;
      this.missing_mapping_column = missing_mapping_columns;
      if (this.validation_done === newValidation) {
        return;
      }

      this.validation_done = newValidation;
    },
    isColumnNameValid(header: any) {
      let isEmptyMapping =
        this.column_mapping_indexes &&
        this.column_mapping_indexes != null &&
        isObjectEmtpy(this.column_mapping_indexes)
          ? true
          : false;
      let isValid = false;

      if (header.name == 'id') {
        return true;
      }

      for (const column of this.dropdownColumns) {
        if (header.name === column.techName) {
          isValid = true;
          break;
        }
      }

      if (
        isValid &&
        isEmptyMapping &&
        this.hasOriginalIndex(header.org_index, header) === true
      ) {
        this.addInMapping(header.org_index, header.name);
      }
      return isValid;
    },
    addInMapping(selectedIndex: any, column_name: string) {
      this.column_mapping_indexes[column_name] = Number(selectedIndex);
    },
    updateLineItemsForApi() {
      if (this.isReadOnly) {
        return;
      }
      this.$emit(
        'updateExtractionDataForSave',
        'mapping',
        this.getColumnMappingIndexes(),
      );
    },
    isColumnGroupBy(index: string) {
      let group_column = '';
      if (this.group_column) {
        group_column = this.group_column;
      }

      if (group_column === null) {
        group_column = '';
      }

      return group_column == index ? true : false;
    },
    getColumnGroupBy() {
      let group_column = '';
      if (this.group_column) {
        group_column = this.group_column;
      }

      if (group_column === null) {
        group_column = '';
      }
      return group_column;
    },
    isColumnVisible(index: string, column: any) {
      let visbile = true;
      if (!index || !this.columns_to_hide || this.columns_to_hide.length == 0) {
        return visbile;
      }

      if (this.columns_to_hide.includes(index) || column.name == 'UUID') {
        visbile = false;
      }

      return visbile;
    },
    isCustomColumnHidden(column_name: string) {
      let hidden = false;
      if (
        !this.custom_columns_to_hide ||
        this.custom_columns_to_hide.length == 0
      ) {
        return hidden;
      }

      for (const column of this.custom_columns_to_hide) {
        if (column === column_name) {
          hidden = true;
          break;
        }
      }

      return hidden;
    },
    isRowDeleted(line: any) {
      let UUID = this.getLineUuid(line);
      if (this.rows_to_delete.includes(UUID)) {
        return false;
      }
      return true;
    },
    getLineUuid(line: any) {
      let UUID = '';
      for (let [index, column] of line.entries()) {
        if (column.techName == 'UUID') {
          UUID = column.value;
          break;
        }
      }
      return UUID;
    },
    getLineItemRowsToHide() {
      this.rows_to_delete = [];
      if (
        !(
          this.docStore.record &&
          this.docStore.record.tables &&
          this.docStore.record.tables[0] &&
          this.docStore.record.tables[0].hasOwnProperty('extraction_info')
        )
      ) {
        return;
      }
      for (let [key, value] of Object.entries(
        this.docStore.record.tables[0].extraction_info,
      )) {
        if (
          this.docStore.record.tables[0].extraction_info[key].hasOwnProperty(
            'rows_to_delete',
          )
        ) {
          this.rows_to_delete =
            this.docStore.record.tables[0].extraction_info[key].rows_to_delete;
        }
      }

      if (
        Array.isArray(this.rows_to_delete) &&
        this.rows_to_delete.length > 0
      ) {
        this.rows_to_delete = this.rows_to_delete[0].split(' ');
        return;
      }
      this.rows_to_delete = [];
    },
    addToRowToDelete(line: any) {
      for (let [index, column] of line.entries()) {
        if (column.techName == 'UUID') {
          this.rows_to_delete.push(column.value);
          break;
        }
      }
    },
    setRowToDeleteForApi() {
      if (
        !this.docStore.record.tables[0] ||
        !this.docStore.record.tables[0].hasOwnProperty('extraction_info')
      ) {
        return;
      }
      let rows_to_delete = [this.rows_to_delete.join(' ')];
      this.$emit(
        'updateExtractionDataForSave',
        'rows_to_delete',
        rows_to_delete,
      );
    },
    inputKeyDown(event: any) {
      if (this.training_mode) {
        event.preventDefault();
        event.target.blur();
        notify.error(this.$t('manual_change'));
        return;
      }
    },
    async inputValueChanges(column_name: string, rowId: string) {
      const columnValue =
        this.lineDataObj[rowId]['columns'][column_name].formatted_value;
      this.lineDataObj[rowId]['columns'][column_name].value = columnValue;
      const localeObj = this.docStore.record.amount_format_locale.split('.');
      if (
        localeObj[0] != 'en_US' &&
        this.lineItemLayout.hasOwnProperty(column_name) &&
        this.lineItemLayout[column_name].column_type === 'AMOUNT'
      ) {
        this.lineDataObj[rowId]['columns'][column_name].value =
          await this.convertValueAccordingToLocale(
            columnValue,
            localeObj[0],
            'en_US',
          );
        this.lineDataObj[rowId]['columns'][column_name].content = columnValue;
      }
      this.updateJsonForLineItems(column_name, rowId);
    },
    updateJsonForLineItems(column_name: string, rowId: string) {
      // Runs on every cell edit. Find the single target row/column directly and
      // stop, instead of scanning every row x column of the table each time.
      const rows = this.docStore.record.tables[0].rows;
      const row = rows.find((r: any) => r.id === rowId);
      if (row) {
        const columnIndex = row.columns.findIndex(
          (c: any) => c.name === column_name,
        );
        if (columnIndex !== -1) {
          row.columns[columnIndex] =
            this.lineDataObj[rowId].columns[column_name];
        }
      }

      this.dispatchEventToSaveTableChanges();
    },
    setJsonForLineItems() {
      Array.from(this.docStore.record.tables[0].rows).forEach(
        (row: any, index: any) => {
          const row_id = row.id;
          const row_data = this.lineDataObj[row_id];
          this.docStore.record.tables[0].rows[index] = row_data;
        },
      );

      this.dispatchEventToSaveTableChanges();
    },

    // this functions need to be refactor as now data is directaly being saved in the store
    dispatchEventToSaveTableChanges(save_to_server = false) {
      this.docStore.confirmationForPoConnectionReset = true;
      const event = new CustomEvent('update_table_data', {
        detail: {
          tables: this.docStore.record.tables,
          save_to_server: save_to_server,
        },
      });
      document.dispatchEvent(event);
    },
    hasLineItems() {
      if (
        !this.tableRows ||
        Object.keys(this.tableRows).length === 0 ||
        !this.is_manual_training_allowed
      ) {
        return false;
      }
      return true;
    },
    openAdvanceSettings() {
      this.adv_column_options = [];
      for (const column of this.dropdownColumns) {
        this.adv_column_options.push(
          Object.assign(
            {},
            {
              value: column.techName,
              label: column.header,
            },
          ),
        );
      }
      this.setAdvSettings();
      this.openAdvSettings = true;
    },
    setAdvSettings() {
      this.move_extra_rows_to = '';
      this.header_rows_count = 1 as number;
      this.extra_columns = [] as any;

      if (!this.formatting_options) {
        return;
      }

      if (
        this.formatting_options.hasOwnProperty('merge_extra_lines_to') &&
        this.formatting_options.merge_extra_lines_to !== null
      ) {
        this.move_extra_rows_to = this.formatting_options.merge_extra_lines_to;
      }

      if (
        this.formatting_options.hasOwnProperty('header_rows_count') &&
        this.formatting_options.header_rows_count !== null
      ) {
        this.header_rows_count = this.formatting_options.header_rows_count;
      }

      if (
        this.formatting_options.hasOwnProperty('extra_cols') &&
        this.formatting_options.extra_cols !== null
      ) {
        this.extra_columns = this.formatting_options.extra_cols;
      }

      if (
        this.formatting_options.hasOwnProperty('group_column') &&
        this.formatting_options.group_column !== null
      ) {
        this.group_column = this.formatting_options.group_column;
      }

      if (
        this.formatting_options.hasOwnProperty('min_group_rows') &&
        this.formatting_options.min_group_rows !== null
      ) {
        this.min_group_rows = this.formatting_options.min_group_rows;
      }

      if (
        this.formatting_options.hasOwnProperty('max_group_rows') &&
        this.formatting_options.max_group_rows !== null
      ) {
        this.max_group_rows = this.formatting_options.max_group_rows;
      }

      if (
        this.formatting_options.hasOwnProperty('distinct_group_column') &&
        this.formatting_options.distinct_group_column !== null
      ) {
        this.distinct_group_column =
          this.formatting_options.distinct_group_column;
      }

      if (
        this.formatting_options.hasOwnProperty('reverse_grouping') &&
        this.formatting_options.reverse_grouping !== null
      ) {
        this.reverse_grouping = this.formatting_options.reverse_grouping;
      }

      if (
        this.formatting_options.hasOwnProperty('split_text') &&
        this.formatting_options.split_text !== null
      ) {
        this.split_text = this.formatting_options.split_text;
      }
    },
    async formatWthAdvSettings() {
      await this.requestReformate();
      this.openAdvSettings = false;
    },
    advSettingNewFieldColumnSelected(fieldName: string, attributeName: string) {
      if (this.new_field_model[attributeName]) {
        this.new_field_model[fieldName] =
          this.new_field_model[attributeName].value;
        return;
      }
      this.new_field_model[fieldName] = '';
    },
    saveNewFieldForAdvSettings() {
      this.new_field_model['pattern_invalid'] = false;
      this.new_field_model['key_invalid'] = false;
      this.new_field_model['source_invalid'] = false;
      let validate = true;
      if (
        this.new_field_model['pattern'] &&
        !isRegexPatternValid(this.new_field_model['pattern'])
      ) {
        this.new_field_model['pattern_invalid'] = true;
        validate = false;
      }

      if (!this.new_field_model['key'] || this.new_field_model['key'] == '') {
        this.new_field_model['key_invalid'] = true;
        validate = false;
      }

      if (
        !this.new_field_model['source'] ||
        this.new_field_model['source'] == ''
      ) {
        this.new_field_model['source_invalid'] = true;
        validate = false;
      }

      if (!validate) {
        return;
      }

      let label = this.new_field_model['label'];
      if (!label) {
        label = this.new_field_model['key'].toUpperCase();
      }

      if (!this.extra_columns) {
        this.extra_columns = [];
      }
      this.extra_columns.push({
        field_key: this.new_field_model['key'].toUpperCase(),
        source_field: this.new_field_model['source'].toUpperCase(),
        label: label,
        pattern: this.new_field_model['pattern'].toUpperCase(),
      });

      this.addFieldsDialog = false;
    },
    addFieldForAdvSettings() {
      this.addFieldsDialog = true;
      this.new_field_model = {} as dynamicObj;
    },
    removeFieldFromSettings(index: any) {
      index = Number(index);
      if (index > -1) {
        this.extra_columns.splice(index, 1);
      }
    },
    async revertChanges(confirmed = false) {
      if (confirmed === false) {
        this.revert_changes_confirm_dialog = true;
        return;
      }

      this.revert_changes_confirm_dialog = false;
      this.resetFormatSettings();
      await this.requestReformate();
    },
    isViewPo() {
      if (this.$route.fullPath.match(/po-matching/g)) {
        this.is_po_view = true;
      }
    },
    refactorApiData() {
      this.resetFormatSettings();
      this.setFormatOptions();
      this.setAdvSettings();
      this.prepareTableLayoutObj();
      this.prepareTableColumn();
      this.prepareTableRowsAndRowObj();
      // prepare line Item headers
      this.sortTableColumn();
      this.validateLineItemColumns();
      this.prepareDisabledCstmColumnsList();
      this.initTableColumnResize(this.tableId);
    },
    setFormatOptions() {
      this.formatting_options = {};

      // A document without an extracted table has `tables: []`, so the entry
      // has to be resolved before anything is written back onto it.
      const table =
        this.docStore.record.tables && this.docStore.record.tables.length > 0
          ? this.docStore.record.tables[0]
          : null;

      if (table && isObject(table.formatting_options)) {
        this.formatting_options = table.formatting_options;
      }

      if (table) {
        table.formatting_options = this.formatting_options;
      }

      if (
        this.formatting_options.hasOwnProperty('mapping') &&
        this.formatting_options.mapping !== null
      ) {
        this.column_mapping_indexes = Object.assign(
          {},
          this.formatting_options.mapping,
        );
      }

      if (
        this.formatting_options.hasOwnProperty('columns_to_hide') &&
        this.formatting_options.columns_to_hide !== null
      ) {
        this.columns_to_hide = Object.assign(
          [],
          this.formatting_options.columns_to_hide,
        );
      }
      if (
        this.formatting_options.hasOwnProperty('custom_columns_to_hide') &&
        this.formatting_options.custom_columns_to_hide !== null
      ) {
        this.custom_columns_to_hide = Object.assign(
          [],
          this.formatting_options.custom_columns_to_hide,
        );
      }

      if (
        !this.formatting_options.hasOwnProperty('column_origins') ||
        isUndefinedOrNull(this.formatting_options.column_origins) ||
        !isObject(this.formatting_options.column_origins)
      ) {
        if (table) {
          table.formatting_options.column_origins = {};
        }
        this.formatting_options.column_origins = {};
      }
      if (
        isUndefinedOrNull(this.formatting_options.extract_from) ||
        !isObject(this.formatting_options.extract_from)
      ) {
        if (table) {
          table.formatting_options.extract_from = {};
        }
        this.formatting_options.extract_from = {};
      }
    },
    resetRows() {
      this.tableRows = [] as any;
      this.lineDataObj = [] as any;
      this.lineItemsErrors = {} as { [k: string]: any };
    },
    resetFormatSettings() {
      this.move_extra_rows_to = '';
      this.header_rows_count = 1;
      this.extra_columns = [] as any;
      this.group_column = '';
      this.min_group_rows = 1;
      this.max_group_rows = null;
      this.distinct_group_column = false;
      this.reverse_grouping = false;
      this.column_mapping_indexes = {} as { [k: string]: any };
      this.columns_to_hide = [] as any;
      this.custom_columns_to_hide = [] as any;
      this.split_text = false;
    },
    setTableData(data: dynamicObj) {
      this.docStore.record.tables[0] = data;
    },

    prepareTableRowsAndRowObj() {
      this.docStore.confirmationForPoConnectionReset = true;
      this.tableRows = [];
      this.lineDataObj = [];
      let lineDataTemp = {} as dynamicObj;
      this.lineItemsErrors = {};
      this.tableRowsLocationsMap.clear();
      // formate table rows data
      if (
        !this.docStore.record.tables ||
        this.docStore.record.tables.length == 0 ||
        !this.docStore.record.tables[0].hasOwnProperty('rows') ||
        this.docStore.record.tables[0].rows.length == 0
      ) {
        return;
      }

      Array.from(this.docStore.record.tables[0].rows).forEach((row: any) => {
        if (row.is_deleted === false) {
          let newRow: dynamicObj = {};
          lineDataTemp[row.id] = JSON.parse(JSON.stringify(row));
          lineDataTemp[row.id].locations_list = [] as any;

          if (row.locations_list) {
            Array.from(row.locations_list).forEach((location: any) => {
              lineDataTemp[row.id].locations_list['page_' + location.page] =
                location;
              if (!this.tableRowsLocationsMap.has('page_' + location.page)) {
                this.tableRowsLocationsMap.set('page_' + location.page, row.id);
              }
            });
          }

          delete lineDataTemp[row.id].columns;
          lineDataTemp[row.id]['columns'] = [] as any;

          Array.from(row.columns).forEach((column: any) => {
            if (lineDataTemp[row.id].columns[column.name]) {
              return;
            }

            lineDataTemp[row.id].columns[column.name] = JSON.parse(
              JSON.stringify(column),
            );
            const layoutObj = this.docStore.record.tables[0].layout.find(
              (l: any) => l.column_name === column.name,
            );

            if (layoutObj) {
              lineDataTemp[row.id].columns[column.name].column_type =
                layoutObj.column_type;
            }

            lineDataTemp[row.id].columns[column.name].locations_list =
              [] as any;
            if (column.locations_list) {
              Array.from(column.locations_list).forEach((location: any) => {
                lineDataTemp[row.id].columns[column.name].locations_list[
                  'page_' + location.page
                ] = location;
              });
            }

            if (isUndefinedOrNull(column.formatted_value)) {
              column.formatted_value = '';
            }

            newRow[column.name] = column.formatted_value;
            this.prepareMapOfColumnHavingData(column);
          });

          this.addExtraColumnsInRow(lineDataTemp, newRow, row.id);
          this.ensureAllColumnsInRow(newRow, lineDataTemp, row.id, row);
          newRow['id'] = row.id;
          this.tableRows.push(newRow);
          this.setRowErrors(row);
        }
      });

      Object.assign(this.lineDataObj, lineDataTemp);
      this.addExtraColumnsInExportJson();
    },
    prepareMapOfColumnHavingData(column: any) {
      if (columnDataStatusMap.has(column.name)) {
        if (columnDataStatusMap.get(column.name) === false) {
          if (
            column.formatted_value &&
            column.formatted_value != null &&
            column.formatted_value != ''
          ) {
            columnDataStatusMap.set(column.name, true);
          }
        }
      } else {
        if (
          column.formatted_value &&
          column.formatted_value != null &&
          column.formatted_value != ''
        ) {
          columnDataStatusMap.set(column.name, true);
        } else {
          columnDataStatusMap.set(column.name, false);
        }
      }
    },
    addExtraColumnsInRow(lineDataTemp: any, newRow: any, rowId: string) {
      for (let colName of this.layoutExtraColumns) {
        let newColumObj = {
          name: colName,
          value: '',
          content: '',
          locations: [],
          locations_list: [],
          formatted_value: '',
          is_extra_column: true,
        };

        lineDataTemp[rowId].columns[colName] = newColumObj;
        columnDataStatusMap.set(colName, false);
        newRow[colName] = '';
      }
    },
    addExtraColumnsInExportJson() {
      let extraColumnList: any = [];
      for (let colName of this.layoutExtraColumns) {
        let newColumObj = {
          name: colName,
          value: '',
          content: '',
          locations: [],
          locations_list: [],
          formatted_value: '',
          is_extra_column: true,
        };
        extraColumnList.push(newColumObj);
      }

      Array.from(this.docStore.record.tables[0].rows).forEach(
        (row: any, rowIndex: any) => {
          for (let newColumObj of extraColumnList) {
            this.docStore.record.tables[0].rows[rowIndex].columns.push(
              newColumObj,
            );
          }
        },
      );
    },
    ensureAllColumnsInRow(
      newRow: any,
      lineDataTemp: any,
      rowId: string,
      row: any,
    ) {
      for (let col of this.tableColumns) {
        if (!(col.name in newRow)) {
          newRow[col.name] = '';
          let columnObj = {
            name: col.name,
            value: '',
            content: '',
            locations: [],
            locations_list: [],
            formatted_value: '',
          };
          lineDataTemp[rowId]['columns'][col.name] = columnObj;
          row.columns.push(columnObj);
        }
      }
    },
    setRowErrors(row: any) {
      this.lineItemsErrors[row.id] = {} as dynamicObj;
      if (!row.messages || !Array.isArray(row.messages)) {
        return;
      }
      let errors = {} as dynamicObj;
      for (const index in row.messages) {
        let data = row.messages[index];

        if (data.message_code == 'COLUMN_NOT_MAPPED') {
          continue;
        }

        if (!data.message || data.message == '') {
          continue;
        }
        errors[data.message_code] = data.message;
      }

      this.lineItemsErrors[row.id] = errors;
    },
    rowHasErrors(row_id: string) {
      if (
        !this.lineItemsErrors.hasOwnProperty(row_id) ||
        this.lineItemsErrors[row_id] === null ||
        isObjectEmtpy(this.lineItemsErrors[row_id])
      ) {
        return false;
      }

      return true;
    },
    prepareTableLayoutObj() {
      // remove duplicate
      this.dropdownColumns = [];
      let duplicate_columns = {} as dynamicObj;
      this.lineItemLayout = {} as dynamicObj;
      this.initStandardColumns();

      if (
        !(
          this.docStore.record.tables &&
          this.docStore.record.tables.length > 0 &&
          this.docStore.record.tables[0].hasOwnProperty('layout')
        )
      ) {
        return;
      }
      Array.from(this.docStore.record.tables[0].layout).forEach(
        (column: any) => {
          if (
            !duplicate_columns.hasOwnProperty(column.column_name) &&
            column.is_hidden == false
          ) {
            duplicate_columns[column.column_name] = true;

            // prepare Coloum layout
            column['lbl_to_display'] = this.getLabelToDisplay(column);
            this.lineItemLayout[column.column_name] = column;

            this.addStandardColumns(column);

            // prepare Coloum Dropdown
            this.dropdownColumns.push({
              header: column.lbl_to_display,
              techName: column.column_name,
            });
          }
        },
      );

      this.sortMappingColumns();
    },
    sortMappingColumns() {
      if (this.dropdownColumns.length > 0) {
        this.dropdownColumns.sort(function (a: any, b: any) {
          if (a.header < b.header) {
            return -1;
          }
          if (a.header > b.header) {
            return 1;
          }
          return 0;
        });
      }
    },

    initStandardColumns() {
      this.advance_settings_columns = [];
      this.advance_settings_columns.push(
        Object.assign({}, { value: '', label: this.$t('select') }),
      );
      this.advance_settings_columns.push(
        Object.assign({}, { value: '__trash__', label: this.$t('trash') }),
      );
    },
    addStandardColumns(column: any) {
      this.advance_settings_columns.push(
        Object.assign(
          {},
          { value: column.column_name, label: column.column_name },
        ),
      );
    },

    prepareTableColumn() {
      this.tableColumns = [];
      let tempColumnArray: any = {};
      this.layoutExtraColumns = [];

      if (
        !(
          this.docStore.record.tables &&
          this.docStore.record.tables.length > 0 &&
          this.docStore.record.tables[0].hasOwnProperty('rows') &&
          this.docStore.record.tables[0].rows.length > 0
        )
      ) {
        return;
      }

      // for column preparation there will be couple of steps
      // 1. prepare columns from table 0 and row 0
      // 2. columns that do not have data will be move to the end
      // 3. then check table layout for extra columns.
      // 4. before save and export check if table extra columns do not have data then remove those columns to optimize the JSON

      const row = this.docStore.record.tables[0].rows[0];

      if (!row) {
        return;
      }

      let tempLineItemLayout = JSON.parse(JSON.stringify(this.lineItemLayout));

      Array.from(row.columns).forEach((column: any) => {
        let allowed = this.isColumnHidden(row, column);
        if (allowed && column.name != 'id') {
          // Add only those column that are in the layout
          let label = column.name;

          if (this.lineItemLayout.hasOwnProperty(column.name)) {
            label = this.lineItemLayout[column.name].lbl_to_display;
            delete tempLineItemLayout[column.name];
          }

          let org_index = '';
          if (column.org_index != null && column.org_index != undefined) {
            org_index = String(column.org_index);
          }
          let columnItem = {
            name: column.name,
            field: column.name,
            align: 'left',
            label: label,
            is_mapped: column.is_mapped ? column.is_mapped : false,
            org_index: org_index,
            col_origin: 'auto',
            extract_from: '',
          };
          columnItem.col_origin = this.getColumnOrigin(
            this.docStore.record.tables[0],
            column.name,
          );
          columnItem.extract_from = this.getExtractOrigin(
            this.docStore.record.tables[0],
            column.name,
          );

          if (column.hasOwnProperty('org_index') && column.org_index != null) {
            this.tableColumns.push(columnItem);
          } else {
            tempColumnArray[column.name] = columnItem;
          }
        } else {
          delete tempLineItemLayout[column.name];
        }
      });

      for (let [key, value] of Object.entries(tempColumnArray)) {
        this.tableColumns.push(Object.assign({}, value));
      }

      // at the end add extra column in the table that are in the layout
      for (let index in tempLineItemLayout) {
        const column = tempLineItemLayout[index];

        let allowed = !this.isCustomColumnHidden(column.name);
        if (!allowed) {
          delete tempLineItemLayout[column.name];
          continue;
        }

        let columnItem = {
          name: column.column_name,
          field: column.column_name,
          align: 'left',
          label: column.lbl_to_display,
          is_mapped: column.is_mapped ? column.is_mapped : false,
          org_index: '',
          is_extra_column: true,
          col_origin: 'auto',
          extract_from: '',
        };

        columnItem.col_origin = this.getColumnOrigin(
          this.docStore.record.tables[0],
          column.name,
        );
        columnItem.extract_from = this.getExtractOrigin(
          this.docStore.record.tables[0],
          column.name,
        );
        this.tableColumns.push(Object.assign({}, columnItem));
        this.layoutExtraColumns.push(column.column_name);
      }
    },
    sortTableColumn() {
      let columnSourceList = JSON.parse(JSON.stringify(this.tableColumns));
      let columnsWithEmptyData: any = [];
      this.tableColumns = [];

      // sort columns by layout sort_order
      const sortOrderMap = new Map<string, number>();
      if (
        this.docStore.record.tables &&
        this.docStore.record.tables[0] &&
        this.docStore.record.tables[0].layout
      ) {
        Array.from(this.docStore.record.tables[0].layout).forEach((col: any) => {
          if (col.column_name && col.sort_order != null) {
            sortOrderMap.set(col.column_name, col.sort_order);
          }
        });
      }
      columnSourceList.sort((a: any, b: any) => {
        const orderA = sortOrderMap.get(a.name) ?? Number.MAX_SAFE_INTEGER;
        const orderB = sortOrderMap.get(b.name) ?? Number.MAX_SAFE_INTEGER;
        return orderA - orderB;
      });

      // 'id' column (buttons) is always first
      this.tableColumns.push({
        name: 'id', field: 'id', align: 'left', label: '',
        is_mapped: true, org_index: true, sort_order: 0,
      });

      // move empty column to end that do not have org_index
      Array.from(columnSourceList).forEach((item: any, _index: any) => {
        if (
          this.hasOriginalIndex(item.org_index, item) != true &&
          columnDataStatusMap.has(item.name) &&
          columnDataStatusMap.get(item.name) === false
        ) {
          columnsWithEmptyData.push(Object.assign({}, item));
        } else {
          this.tableColumns.push(Object.assign({}, item));
        }
      });

      // sort empty columns alphabetically
      columnsWithEmptyData.sort((a: any, b: any) => {
        let fa = a.field.toLowerCase(),
          fb = b.field.toLowerCase();
        if (fa < fb) {
          return -1;
        }
        if (fa > fb) {
          return 1;
        }
        return 0;
      });

      // add empty columns at the end
      Array.from(columnsWithEmptyData).forEach((item: any, _index: any) => {
        this.tableColumns.push(Object.assign({}, item));
      });
    },
    isColumnHidden(row: any, column: any) {
      let org_index = '';
      if (column.org_index != null && column.org_index != undefined) {
        org_index = String(column.org_index);
      }

      let allowed = true;
      if (org_index !== '') {
        allowed = this.isColumnVisible(org_index, column);
      }

      if (org_index === '') {
        allowed = !this.isCustomColumnHidden(column.name);
      }

      // ACL check: hide column if user has NO_ACCESS permission
      if (allowed) {
        const colId = this.lineItemLayout?.[column.name]?.id;
        if (colId) {
          allowed = Acl.hasColumnPermission(
            this.docStore.record?.doc_type,
            colId,
            FieldPermission.READ_ONLY,
          );
        }
      }

      return allowed;
    },
    async deleteLineItemColumn(colIndex: string) {
      this.columns_to_hide.push(colIndex);
      // Drop any column-name mapping pointing at the deleted column so its
      // name doesn't stay reserved and block re-assignment (DOCB-13166).
      if (this.column_mapping_indexes) {
        for (const name of Object.keys(this.column_mapping_indexes)) {
          if (this.column_mapping_indexes[name] == colIndex) {
            delete this.column_mapping_indexes[name];
          }
        }
      }
      if (this.group_column != null && this.group_column === colIndex) {
        this.group_column = '';
      }
      await this.requestReformate();
    },
    getColumnToHide() {
      if (!Array.isArray(this.columns_to_hide)) {
        return '';
      }

      return this.columns_to_hide.join();
    },
    removeLineItem(lineId: string) {
      // mark item as deleted
      Array.from(this.docStore.record.tables[0].rows).forEach((row: any) => {
        if (row.id === lineId) {
          row.is_deleted = true;
          this.$forceUpdate();
          // prepare data for rows
          this.prepareTableRowsAndRowObj();
          return;
        }
      });
      this.dispatchEventToSaveTableChanges();
    },
    async swapColumn(
      data: any,
      index: number,
      colName: string,
      buttonId: string,
    ) {
      if (!this.isViewEditable()) {
        return;
      }

      if (this.selectedColumnHasData(data.techName)) {
        notify.error(this.$t('column_has_value'));
        return;
      }

      let isColumnAlreadymapped = false;
      let isColumnReMapped = false;
      let selectedIndex = index;

      if (this.column_mapping_indexes) {
        for (const name in this.column_mapping_indexes) {
          let keyIndex = this.column_mapping_indexes[name];

          // Skip mappings that point at a deleted (hidden) column: they are
          // stale and must not block re-assigning that column name. Also heals
          // documents left with a dangling mapping (DOCB-13166).
          if (
            Array.isArray(this.columns_to_hide) &&
            this.columns_to_hide.some((hidden: any) => hidden == keyIndex)
          ) {
            continue;
          }

          if (name == data.techName && keyIndex != selectedIndex) {
            isColumnAlreadymapped = true;
            break;
          }
          if (name == colName && keyIndex == selectedIndex) {
            isColumnReMapped = true;
            break;
          }
        }
      }

      if (isColumnAlreadymapped) {
        notify.error(this.$t('COLUMN_ALREADY_MAPPED'));
        return;
      }

      if (isColumnReMapped) {
        delete this.column_mapping_indexes[colName];
      }

      this.addInMapping(selectedIndex, data.techName);
      await this.requestReformate();
      setTimeout(() => {
        this.scrollInToViewCenter(
          document.getElementById(buttonId) as HTMLElement,
        );
      }, 10);
    },
    selectedColumnHasData(column_name: string) {
      let columnHasValue = false;
      for (const key in this.tableRows) {
        const row = this.tableRows[key];
        if (
          row.hasOwnProperty(column_name) &&
          row[column_name] != null &&
          row[column_name] != undefined &&
          row[column_name] != ''
        ) {
          columnHasValue = true;
          break;
        }
      }
      return columnHasValue;
    },
    getTableData() {
      if (
        !(this.docStore.record.tables && this.docStore.record.tables.length > 0)
      ) {
        return {};
      }
      return this.docStore.record.tables[0] as dynamicObj;
    },
    async restoreDeleteColumn(e: any) {
      this.columns_to_hide = [];

      let restore_table_columns = false;
      if (e && e.detail && e.detail.restore_table_columns) {
        restore_table_columns = e.detail.restore_table_columns;
      }

      await this.requestReformate(restore_table_columns);
    },
    async requestReformate(restore_table_columns = false) {
      this.lineItemsloading = true;
      this.resetRows();

      try {
        let response: any;
        let formData = new FormData();
        formData.append('doc_id', this.docId);
        formData.append('group_column', this.getColumnGroupBy());
        formData.append('min_group_rows', this.min_group_rows.toString());
        formData.append(
          'max_group_rows',
          this.max_group_rows ? this.max_group_rows.toString() : '',
        );
        formData.append('header_rows_count', this.header_rows_count.toString());
        formData.append(
          'distinct_group_column',
          this.distinct_group_column.toString(),
        );
        formData.append('reverse_grouping', this.reverse_grouping.toString());
        formData.append(
          'column_mapping_indexes',
          JSON.stringify(this.getColumnMappingIndexes()),
        );
        formData.append('move_extra_rows_to', this.move_extra_rows_to);
        formData.append('extra_columns', JSON.stringify(this.extra_columns));
        formData.append('columns_to_hide', this.getColumnToHide());
        formData.append('data', JSON.stringify(this.getTableData()));
        formData.append(
          'column_origins',
          JSON.stringify(this.getColumnOrigins()),
        );
        formData.append(
          'extract_from',
          JSON.stringify(this.getExtractOrigins()),
        );

        if (restore_table_columns) {
          formData.append('restore_table_columns', true.toString());
        }

        if (this.docStore.record.hasOwnProperty('is_table_training_doc')) {
          formData.append('is_table_training_doc', true.toString());
        }
        formData.append('org_id', getOrgId());
        let token: string = await this.getToken();
        response = await axios.post(api.reformat_table_table_v3, formData, {
          headers: {
            Authorization: token,
          },
        });

        if (response.data.success === false) {
          throw response;
        }

        this.setTableData(response.data);
        this.dispatchEventToSaveTableChanges();
        this.refactorApiData();
        this.lineItemsloading = false;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        this.lineItemsloading = false;
        return;
      }
      this.renderKey++;
    },
    getColumnOrigins() {
      return this.docStore.record.tables[0].formatting_options
        .column_origins as dynamicObj;
    },
    getExtractOrigins() {
      return this.docStore.record.tables[0].formatting_options
        .extract_from as dynamicObj;
    },
    addNewCustomColumn(e: any) {
      this.addColumnDialog = true;
    },
    editColumnData(e: any, columnName: any, rowId: string) {
      if (this.lineDataObj[rowId].hasOwnProperty('custom_row')) {
        return;
      }

      if (this.isRowMode === true) {
        let waitTime = 10;
        // clear old selection
        this.clearOldSelection();
        if (e.target.closest('label')) {
          (e.target.closest('label') as HTMLElement).classList.add(
            'active-border-2px',
          );
        }

        let currentColumnObj: any;
        currentColumnObj = this.lineDataObj[rowId].columns[columnName];

        let columnSelection = true;

        if (currentColumnObj && currentColumnObj.locations_list) {
          let locationList = currentColumnObj.locations_list;

          // DOCB-6323: with reverse grouping the column's own (anchor) location
          // is the LAST entry — merged locations are inserted at the front —
          // so both the "current page is among the column's pages, stay put"
          // short-circuit and the "first key" jump target below read the wrong
          // end of the list. Navigate to the anchor page instead. See the note
          // in loadAppropriatePage.
          const anchorPageNo = this.reverse_grouping
            ? this.getAnchorPageNo(locationList)
            : null;

          if (anchorPageNo !== null) {
            columnSelection = false;
            if (anchorPageNo !== +this.currentPageNo) {
              waitTime = 200;
              this.$emit('loadNewPageImage', anchorPageNo - 1);
            }
          } else if (locationList.hasOwnProperty('page_' + this.currentPageNo)) {
            columnSelection = false;
          } else if (Object.entries(locationList).length != 0) {
            waitTime = 200;
            for (const key in locationList) {
              columnSelection = false;
              let pageNo = +locationList[key].page - 1;
              this.$emit('loadNewPageImage', pageNo);
              break;
            }
          } else {
            this.loadAppropriatePage(rowId);
          }
        }

        // wait until the new page image is loaded
        setTimeout(() => {
          if (columnSelection === false) {
            let detailObj = { rowId: rowId, columnName: columnName };
            this.getTableRowsAreas({ detail: detailObj });

            // wait until the table areas are prepared
            setTimeout(() => {
              let selectedArea: HTMLElement | null = $(
                '#' + 'draw_' + columnName,
              );
              if (selectedArea) {
                (
                  selectedArea.querySelector(
                    '.select-areas--outline',
                  ) as HTMLElement
                ).style.opacity = '0';

                let selection = selectedArea.querySelector(
                  '.select-areas--background_area',
                ) as HTMLElement;
                selection.style.border = '2px';
                selection.style.borderStyle = 'solid';
                selection.style.borderColor = '#8800ff';

                this.oldSelectedColumnName = columnName;

                this.scrollInToViewCenter(selection);

                // remove existing correction dialog
                this.removeExistingConfirmationOverlays();

                if (
                  currentColumnObj &&
                  this.addExtractionMethodClass(currentColumnObj) !== ''
                ) {
                  setTimeout(() => {
                    let column_value: string =
                      e.target.closest('td').dataset.columnValue;
                    let score_description: string =
                      e.target.closest('td').dataset.scoreDescription;
                    let detailObj = {
                      value: column_value,
                      score: score_description,
                      selection: selection,
                    };

                    const event = new CustomEvent('prepare_overlay', {
                      detail: detailObj,
                    });
                    document.dispatchEvent(event);
                  }, 20);
                }
              }
            }, waitTime);
          } else {
            // if no area for the column let the user select one.
            this.showNotification(this.$t('SELECT_AREA'));

            let detailObj = {
              rowId: rowId,
              columnName: columnName,
              onlySelectedRow: true,
            };
            this.getTableRowsAreas({ detail: detailObj });

            // wait until the table areas are prepared
            setTimeout(() => {
              const event = new CustomEvent('enable_column_selection', {
                detail: rowId,
              });
              document.dispatchEvent(event);
            }, 10);
          }
        }, 10);
      } else {
        this.loadAppropriatePage(rowId);
        setTimeout(() => {
          let detailObj = {
            rowId: rowId,
            columnName: columnName,
            onlySelectedRow: true,
          };
          this.drawSelectedRow({ detail: detailObj });

          setTimeout(() => {
            let selectedArea: HTMLElement | null = $('#' + 'draw_' + rowId);
            if (selectedArea) {
              this.oldSelectedColumnName = columnName;
              let selection = selectedArea.querySelector(
                '.select-areas--background_area',
              ) as HTMLElement;
              this.scrollInToViewCenter(selection);
            }
          }, 40);
        }, 100);
      }
    },
    clearOldSelection() {
      if (this.oldSelectedColumnName != '') {
        let oldSelectedArea: HTMLElement | null = $(
          '#' + 'draw_' + this.oldSelectedColumnName,
        );
        if (oldSelectedArea) {
          let oldSelection = oldSelectedArea.querySelector(
            '.select-areas--background_area',
          ) as HTMLElement;
          let selectionBackground =
            oldSelection.style.background.split('100%)');
          oldSelection.style.background = rowRgbaColor + selectionBackground[1];
        }
      }

      let elems = document
        .querySelector('#' + this.tableId)!
        .querySelectorAll('label.active-border-2px');
      Array.from(elems).forEach((element: any) => {
        element.classList.remove('active-border-2px');
      });

      let image_container_el = document.querySelector(
        '#screenshot_container',
      ) as HTMLElement;
      let imageArea = image_container_el.querySelectorAll(
        'div.select-areas--outline',
      );

      Array.from(imageArea).forEach((element: any) => {
        element.style.opacity = '0.2';
        if ((element as HTMLElement).nextSibling) {
          ((element as HTMLElement).nextSibling as HTMLElement).style.border =
            'unset';
        }
      });
    },
    /**
     * DOCB-6323: page number (1-based) of the anchor location in a
     * `locations_list`, i.e. the page the selected row/column's own content was
     * extracted from. Returns null when there is no location at all.
     *
     * `locations_list` is in ascending document order in both grouping modes;
     * the anchor sits at the front with normal grouping and at the back with
     * reverse grouping (doc2-api `combine_rows` appends vs. inserts at 0).
     */
    getAnchorPageNo(locationsList: any): number | null {
      if (!locationsList) {
        return null;
      }
      const pageKeys = Object.keys(locationsList);
      if (pageKeys.length === 0) {
        return null;
      }
      const anchorKey = this.reverse_grouping
        ? pageKeys[pageKeys.length - 1]
        : pageKeys[0];
      return +locationsList[anchorKey].page;
    },
    loadAppropriatePage(rowId: string) {
      let row = this.lineDataObj[rowId];
      if (!row || !row.locations_list) {
        return;
      }

      // DOCB-6323: a grouped row can straddle a page break, so it carries
      // locations on several pages. doc2-api emits them in ascending document
      // order in BOTH grouping modes (combine_rows APPENDS the merged location
      // under normal grouping and INSERTS it at the front under reverse
      // grouping), but the anchor row — the physical row that owns the group
      // value, i.e. the one the user is pointing at — is at the opposite end:
      //   normal  grouping -> [anchor, below, below]
      //   reverse grouping -> [above, above, anchor]
      // Deriving the page from the un-reversed order therefore parks the viewer
      // on the page ABOVE the anchor whenever reverse grouping is on, and the
      // legacy "current page is among the row's pages, stay put" short-circuit
      // makes that permanent: selecting a row anchored on page 2 while page 1
      // is open never navigated.
      if (this.reverse_grouping) {
        const anchorPage = this.getAnchorPageNo(row.locations_list);
        if (anchorPage === null || anchorPage === +this.currentPageNo) {
          return;
        }
        this.$emit('loadNewPageImage', anchorPage - 1);
        return;
      }

      let rowKey = '';

      for (const key in row.locations_list) {
        // found area is in current page looks good. else move to any page on which area exists
        if (row.locations_list[key].page === this.currentPageNo) {
          rowKey = key;
          break;
        }
        rowKey = key;
      }

      if (rowKey != '') {
        let pageNo = +row.locations_list[rowKey].page - 1;
        this.$emit('loadNewPageImage', pageNo);
      }
    },
    drawSelectedRow(e: any) {
      let rowId = '';
      let columnName = null;
      if (e.detail != undefined && e.detail.columnName) {
        rowId = e.detail.rowId;
        columnName = e.detail.columnName;
      }

      let areaList: any = [];

      if (this.lineDataObj[rowId]) {
        if (
          this.lineDataObj[rowId].locations_list &&
          this.lineDataObj[rowId].locations_list['page_' + this.currentPageNo]
        ) {
          areaList.push({
            id: rowId,
            type: 'row',
            row_id: '',
            background: rowRgbaColorStr,
            opacity: '1',
            coord:
              this.lineDataObj[rowId].locations_list[
                'page_' + this.currentPageNo
              ].coords[0],
          });
        }

        let column = this.lineDataObj[rowId].columns[columnName];
        if (
          column &&
          column.locations_list &&
          column.locations_list['page_' + this.currentPageNo]
        ) {
          areaList.push({
            id: columnName,
            row_id: e.detail.rowId,
            type: 'column',
            background: rowRgbaColorStr,
            opacity: '1',
            coord:
              column.locations_list['page_' + this.currentPageNo].coords[0],
          });
        }
      }

      let tableData = { columns: [], table_areas: [] };

      tableData.table_areas = areaList;
      SessionStorage.set('table_rows_data', JSON.stringify(tableData));

      const event = new CustomEvent('prepare_customized_areas');
      document.dispatchEvent(event);
    },
    getTableRowsAreas(e: any) {
      let rowId = 'all_rows';
      let columnName = null;
      if (e.detail != undefined && e.detail.columnName) {
        rowId = e.detail.rowId;
        columnName = e.detail.columnName;
      }

      let areaList: any = [];
      for (const key in this.lineDataObj) {
        if (
          this.lineDataObj[key] &&
          this.lineDataObj[key].locations_list['page_' + this.currentPageNo]
        ) {
          areaList.push({
            id: key,
            type: 'row',
            row_id: '',
            background:
              e.detail != undefined && e.detail.rowId === key
                ? ''
                : 'linear-gradient( rgba(211, 211, 211, 0.5) 100%, rgba(0, 0, 0, 0.5)100%),',
            opacity:
              e.detail != undefined && e.detail.rowId === key ? '1' : '1',
            coord:
              this.lineDataObj[key].locations_list['page_' + this.currentPageNo]
                .coords[0],
          });
        }
      }

      if (
        e.detail &&
        !e.detail.onlySelectedRow &&
        this.lineDataObj.hasOwnProperty(e.detail.rowId)
      ) {
        let columns = this.lineDataObj[e.detail.rowId].columns;

        for (const key in columns) {
          if (
            columns[key].locations_list &&
            columns[key].locations_list.hasOwnProperty(
              'page_' + this.currentPageNo,
            )
          ) {
            areaList.push({
              id: key,
              row_id: e.detail.rowId,
              type: 'column',
              background: this.columnDefaultBackground(),
              opacity: 1,
              coord:
                columns[key].locations_list['page_' + this.currentPageNo]
                  .coords[0],
            });
          }
        }
      }

      this.$emit(
        'setTableRowCorrdinates',
        JSON.stringify(areaList),
        columnName,
        rowId,
      );
    },
    columnDefaultBackground() {
      return rowRgbaColorStr;
    },
    hasOriginalIndex(index: any, item: any) {
      let hasIndex = false;
      if (index !== '') {
        hasIndex = true;
      }
      return hasIndex;
    },
    getScoreDescription(column: any) {
      let score_description = '';
      if (
        column &&
        column.hasOwnProperty('score_description') &&
        column.score_description !== '' &&
        column.score_description != null
      ) {
        score_description = column.score_description;
      }

      return String(score_description);
    },
    TriggerSplitText() {
      this.split_text_confirm_dialog = false;
      this.openAdvSettings = false;
      const event = new CustomEvent('perform_split_text', {
        detail: this.split_text,
      });
      document.dispatchEvent(event);
    },
    disableCustomColumn(name: string) {
      if (
        !this.formatting_options.hasOwnProperty('custom_columns_to_hide') ||
        this.formatting_options.custom_columns_to_hide === null
      ) {
        this.formatting_options.custom_columns_to_hide = Object.assign([]);
      }

      this.formatting_options.custom_columns_to_hide.push(name);
      this.refactorApiData();
      this.$forceUpdate();
      this.dispatchEventToSaveTableChanges(true);
    },
    prepareDisabledCstmColumnsList() {
      this.disableColumnList = [];
      if (
        !(
          this.docStore.record.tables &&
          this.docStore.record.tables.length > 0 &&
          this.docStore.record.tables[0].hasOwnProperty('layout')
        )
      ) {
        return;
      }

      Array.from(this.docStore.record.tables[0].layout).forEach(
        (column: any) => {
          if (this.isCustomColumnHidden(column.column_name) === true) {
            let newRow: dynamicObj = {};
            newRow['name'] = column.column_name;
            newRow['label'] = this.getLabelToDisplay(column);
            this.disableColumnList.push(newRow);
          }
        },
      );
    },
    openDisabledCstmColumnsView() {
      if (
        !(
          this.docStore.record.tables &&
          this.docStore.record.tables.length > 0 &&
          this.docStore.record.tables[0].hasOwnProperty('layout')
        )
      ) {
        return;
      }
      this.openDisableColumnListView = true;
    },
    enableCustomColumn(e: any) {
      if (!e || !e.detail) {
        return;
      }
      var index = this.formatting_options.custom_columns_to_hide.indexOf(
        e.detail,
      );
      if (index !== -1) {
        this.formatting_options.custom_columns_to_hide.splice(index, 1);
      }
      this.refactorApiData();
      this.dispatchEventToSaveTableChanges(true);
    },
    customColumnCreated(e: any) {
      if (!e || !e.detail || !e.detail.tables) {
        return;
      }
      this.addColumnDialog = false;
      this.setTableData(e.detail.tables);
      this.dispatchEventToSaveTableChanges();
      this.refactorApiData();
    },
    createRowJson() {
      let newRowJson = JSON.parse(
        JSON.stringify(this.docStore.record.tables[0].rows[0]),
      );
      newRowJson.id = Date.now();
      newRowJson.ids = [];
      newRowJson.content = '';
      newRowJson.locations = [];
      newRowJson.locations_list = [];
      newRowJson.is_deleted = false;
      newRowJson.messages = [];
      newRowJson.custom_row = true;

      Array.from(newRowJson.columns).forEach(
        (column: any, columnIndex: any) => {
          column.content = '';
          column.locations = [];
          column.locations_list = [];
          column.value = '';
          column.formatted_value = '';
        },
      );

      this.docStore.record.tables[0].rows.push(newRowJson);
      this.$forceUpdate();
      this.prepareTableRowsAndRowObj();
    },
    prepareRegexData(columnName: string) {
      this.docStore.regex.clear();
      this.selectedColumn = columnName;

      Array.from(this.docStore.record.tables[0].rows).forEach(
        (row: any, rowIndex: any) => {
          Array.from(row.columns).forEach((column: any, columnIndex: any) => {
            if (column.name === columnName) {
              if (
                column.hasOwnProperty('rule') &&
                column.hasOwnProperty('valuePattern')
              ) {
                this.docStore.regex.set(column.rule, column.valuePattern);
              }
            }
          });
        },
      );

      this.showRegexDlg = true;
    },
    updateRegexByRule() {
      this.showRegexDlg = false;
      Array.from(this.docStore.record.tables[0].rows).forEach(
        (row: any, rowIndex: any) => {
          Array.from(row.columns).forEach((column: any, columnIndex: any) => {
            if (column.name === this.selectedColumn) {
              if (
                column.hasOwnProperty('rule') &&
                column.hasOwnProperty('valuePattern')
              ) {
                this.docStore.record.tables[0].rows[rowIndex].columns[
                  columnIndex
                ].valuePattern = this.docStore.regex.get(column.rule);
              }
            }
          });
        },
      );

      this.refactorApiData();
    },
    setShowRegexDlg(showRegexDlg: boolean) {
      this.showRegexDlg = showRegexDlg;
    },
    highliteFirstRowOfCurrentPage() {
      if (this.tableRowsLocationsMap.has('page_' + this.currentPageNo)) {
        const rowId = this.tableRowsLocationsMap.get(
          'page_' + this.currentPageNo,
        );
        const rowElement = $('#tbl_row_' + rowId) as HTMLElement;
        if (rowElement) {
          this.scrollInToViewStart(rowElement);
          setTimeout(() => {
            rowElement.classList.add('light-grey-with-effect');
            setTimeout(() => {
              rowElement.classList.remove('light-grey-with-effect');
            }, 1400);
          }, 500);
        }
      }
    },
    getBackgroundColor(columnObj: any) {
      let background = '';

      if (
        columnObj.hasOwnProperty('is_auto_filled') &&
        columnObj.is_auto_filled == true
      ) {
        background = this.is_auto_filled_color;
      } else if (
        columnObj.hasOwnProperty('is_missing') &&
        columnObj.is_missing == true
      ) {
        background = this.is_missing_color;
      }

      return background;
    },
    displayFieldErrors() {
      this.refactorApiData();
    },
    updateColumnOrigin(data: any) {
      if (
        !data ||
        !data.hasOwnProperty('column_name') ||
        !data.hasOwnProperty('origin')
      ) {
        return;
      }

      if (data.column_name == '') return;
      if (data.language_origin == '') return;

      let update = false;
      Array.from(this.docStore.record.tables[0].rows).forEach(
        (row: any, rowIndex: any) => {
          Array.from(row.columns).forEach((column: any, columnIndex: any) => {
            if (column.name === data.column_name) {
              column.col_origin = data.origin;
              update = true;
            }
          });
        },
      );

      this.docStore.record.tables[0].formatting_options.column_origins[
        data.column_name
      ] = data.origin;

      if (update) {
        this.requestReformate();
      }
    },
    updateExtractOrigin(data: any) {
      if (
        !data ||
        !data.hasOwnProperty('column_name') ||
        !data.hasOwnProperty('origin')
      ) {
        return;
      }

      if (data.column_name == '') return;
      // if (data.extract_origin == '') return;

      let update = false;
      Array.from(this.docStore.record.tables[0].rows).forEach(
        (row: any, rowIndex: any) => {
          Array.from(row.columns).forEach((column: any, columnIndex: any) => {
            if (column.name === data.column_name) {
              column.extract_from = data.origin;
              update = true;
            }
          });
        },
      );

      this.docStore.record.tables[0].formatting_options.extract_from[
        data.column_name
      ] = data.origin;

      if (update) {
        this.requestReformate();
      }
    },

    getTextAlign(columnType: string) {
      if (['AMOUNT', 'NUMBER'].includes(columnType)) {
        return 'right';
      }
      return 'left';
    },
  },
  computed: {
    filteredColumns(): any {
      if (this.searchColumn === '') {
        return this.dropdownColumns;
      }
      let options = [] as dynamicObj[];
      const needle = this.searchColumn.toLowerCase();
      options = this.dropdownColumns.filter(
        (item: any) => item.header.toLowerCase().indexOf(needle) > -1,
      );
      return options;
    },
  },
  setup() {
    const docStore = useDocumentStore();
    const { is_manual_training_allowed } = storeToRefs(docStore);

    const doc_line_items_store = useLineItemStore();
    const { validation_done, missing_mapping_column } =
      storeToRefs(doc_line_items_store);

    let data: any = [];
    let model = {} as { [k: string]: any };
    const filter = ref('');
    return {
      searchColumn: ref(''),
      is_manual_training_allowed,
      is_line_item_validated: validation_done,
      missing_mapping_column,
      filter,
      docStore,
      headers: ref(),
      lineitems: ref(),
      move_extra_rows_to: ref(''),
      header_rows_count: ref(1),
      min_group_rows: ref(1),
      max_group_rows: ref(),
      distinct_group_column: ref(false),
      reverse_grouping: ref(false),
      group_column: ref(''),
      column_mapping_indexes: ref(model),
      columns_to_hide: ref(data),
      custom_columns_to_hide: ref(data),
      addFieldsDialog: ref(false),
      extra_columns: ref(data),
      poEditRestrictDialog: ref(false),
      poEditRestrictMessage: ref(''),
      new_field_model: ref(model),
      new_column_model: ref(model),
      revert_changes_confirm_dialog: ref(false),
      adv_column_options: data,
      advance_settings_columns: ref([] as any),
      headerRowCountRules: [
        (val: number) => val !== null || 'Please type number',
        (val: number) => (val > 0 && val < 100) || 'Please type number',
      ],

      showNotification(message: string) {
        notify.info(message);
      },

      lineDataObj: ref(data),
      lineItemsErrors: ref(model),
      lineItemLayout: ref(data),
      tableColumns: ref(data),
      tableRows: ref(data),
      formatting_options: ref(model),
      addColumnDialog: ref(false),
      headerKey: ref(''),
      headerLable: ref(''),
      lineItemsloading: ref(true),
      openDisableColumnListView: ref(false),
      disableColumnList: ref(data),
      split_text: ref(false),
      split_text_confirm_dialog: ref(false),
      tableRowsLocationsMap: ref(new Map()), //this map will contain only first row of all the pages
      layoutExtraColumns: ref([] as any),
    };
  },
});
</script>

