<!--vbase-->
<template>
  <q-btn
    v-if="isPOView"
    round
    color="amber-9"
    padding="xs"
    id="export_po_btn"
    @click="confirmAndExport()"
    icon="import_export"
    class="q-ma-sm po_iterateable_item"
  >
    <q-tooltip>{{ $t('confirm_export') }}</q-tooltip>
  </q-btn>

  <div v-else class="row q-pt-xl full-width" style="display: flex">
    <template v-if="isValidationView">
      <div class="col-sm-12 col-md-12 col-lg-12 q-pb-sm q-pl-sm">
        <q-btn-dropdown
          split
          class="glossy full-width"
          color="primary"
          :label="$t('save')"
          @click="confirmationForSave(false)"
        >
          <q-list class="text-center">
            <q-item
              clickable
              v-close-popup
              @click="confirmRuleSave = true"
              class="border-bottom-bdbdbd min-height-38"
            >
              <q-item-section>
                <q-item-label>{{ $t('save_rules') }}</q-item-label>
              </q-item-section>
            </q-item>

            <q-item
              clickable
              v-close-popup
              @click="confirmationForSave(true)"
              class="border-bottom-bdbdbd min-height-38"
            >
              <q-item-section>
                <q-item-label>{{ $t('save_and_close') }}</q-item-label>
              </q-item-section>
            </q-item>
          </q-list>
        </q-btn-dropdown>
      </div>
    </template>

    <template v-else>
      <div class="col-sm-12 col-md-4 col-lg-4 q-pb-sm q-pl-sm">
        <f-btn
          :label="$t('save')"
          class="full-width"
          @click="confirmationForSave(false)"
        />
      </div>
      <div class="col-sm-12 col-md-4 col-lg-4 q-pl-sm q-pb-sm">
        <f-btn
          :label="$t('save_rules')"
          :class="
            (!is_line_item_validated ? 'btn-disabled' : '') + ' full-width'
          "
          @click="confirmationRuleSave()"
        >
          <q-tooltip v-if="!is_line_item_validated">{{
            $t('missing_mapping_warning')
          }}</q-tooltip>
        </f-btn>
      </div>
      <div class="col-sm-12 col-md-4 col-lg-4 q-pl-sm q-pb-sm">
        <DeleteRulesBtn :docId="docId" @autoDetectTables="autoDetectTables" />
      </div>
    </template>

    <div v-if="po_enable" class="col-sm-12 col-md-5 col-lg-5 q-pb-sm q-pl-sm">
      <f-btn
        :label="$t('po_matching')"
        class="full-width"
        @click="
          isPoView = true;
          confirmationForSave();
        "
      />
    </div>
    <div
      :class="
        po_enable
          ? 'col-sm-12 col-md-7 col-lg-7'
          : 'col-sm-12 col-md-12 col-lg-12'
      "
      class="q-pl-sm"
    >
      <q-btn-dropdown
        split
        class="full-width"
        unelevated
        :class="!enableExportButton ? 'disabled' : ''"
        color="primary"
        :disable="export_request_in_flight"
        @click="confirmAndExport()"
      >
        <template v-slot:label>
          {{ $t('confirm') }}
          <q-tooltip v-if="hasErrors">
            Following fields need to be validated before export:<br />
            <div v-for="item in fieldErrors" :key="item">{{ item }}<br /></div>
          </q-tooltip>
        </template>
        <q-list class="text-center">
          <q-item
            clickable
            v-close-popup
            @click="validateConfigurationAndExport(1)"
            class="border-bottom-bdbdbd min-height-38"
          >
            <q-item-section>
              <q-item-label>{{ $t('confirm_export_next') }}</q-item-label>
            </q-item-section>
          </q-item>
        </q-list>
      </q-btn-dropdown>
    </div>
  </div>

  <q-dialog v-model="confirmRuleSave" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section
        class="row items-center"
        style="justify-content: center; display: flex"
      >
        <span class="q-ml-sm">{{
          $t('SAVE_RULES_WARNING')
        }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn :label="$t('done')" v-close-popup @click="saveRules()" />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog v-model="confirmRedirection" persistent>
    <q-card>
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          {{ $t('confirm') }}
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('NO_NEXT_DOCUMENT') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <q-btn :label="$t('done')" v-close-popup @click="routeToDashboard()" />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog v-model="showConfirmation" persistent>
    <q-card>
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          {{ $t('confirm') }}
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="row items-center">
        <span class="q-ml-sm"
          >You have made some changes related to line Item/PO on saving you may
          lost PO connections</span
        >
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn :label="$t('done')" v-close-popup @click="proceedToSave()" />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog v-model="showUnmatchedPoWarring" persistent>
    <q-card>
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          {{ $t('confirm') }}
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="row items-center">
        <span class="q-ml-sm"
          >You have Some Unmapped PO. Do you still want to continue with
          export?</span
        >
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          :label="$t('done')"
          v-close-popup
          @click="validateConfigurationAndExport(routeType)"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog v-model="showPoMatchWarning" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{
          $t('WARNING_EXPORT_FROM_PO_MATCH')
        }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          :label="$t('po_matching')"
          v-close-popup
          @click="navigateToPOMatch()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import axios from 'axios';
import cache from 'src/utils/cache';
import { storeToRefs } from 'pinia';
import { SessionStorage } from 'quasar';
import { defineComponent, ref } from 'vue';
import { objLen } from 'src/utils/general';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import { allowedDocTypes } from 'src/constants';
import poActionsUtil from 'src/utils/poActionsUtil';
import { ApiExceptions } from 'src/exceptions/index';
import { api, getAuthorizationToken } from 'pages/APIs';
import { documentDetailApiService } from 'src/services';
import { export_request_in_flight } from 'src/services/document/exportRequestGuard';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import DeleteRulesBtn from 'src/components/DeleteRulesBtn.vue';
import {
  getOrgId,
  addOrgIdQueryString,
} from 'src/utils/organization/org_id_helper';
import {
  useDocLockStore,
  useDocumentStore,
  useLineItemStore,
  useDashboardStore,
} from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, poActionsUtil, displayFieldLabel, cache],
  emits: ['setApiData', 'autoDetectTables'],
  props: {
    enableExportButton: Boolean,
    isValidationView: {
      type: Boolean,
      default: false,
    },
    isPOView: {
      type: Boolean,
      default: false,
    },
  },
  components: {
    DeleteRulesBtn,
  },
  watch: {},
  computed: {
    hasErrors: function (): boolean {
      return objLen(this.fieldErrors) > 0;
    },
  },
  data() {
    return {
      docId: '',
      routeType: ref(0),
      isPoView: ref(false),
      moveToDashboard: ref(false),
      showConfirmation: ref(false),
      allowedDoctypes: allowedDocTypes,
      po_module_activate: ref(false),
      showPoMatchWarning: ref(false),
      showUnmatchedPoWarring: ref(false),
    };
  },
  mounted: function () {
    // before browser or tab close clear the cache data
    window.addEventListener('beforeunload', this.onTabClose);
    document.addEventListener('save_data', this.triggerSaveData);
    this.docId = this.$route.params.id as string;
  },
  unmounted: function () {
    window.removeEventListener('beforeunload', this.onTabClose);
    document.removeEventListener('save_data', this.triggerSaveData);
  },
  methods: {
    cleanupDataforApi(data: any) {
      if (
        data &&
        data.hasOwnProperty('doc_type') &&
        this.allowedDoctypes.indexOf(data.doc_type) === -1 &&
        data.hasOwnProperty('tables')
      ) {
        //data.tables = [];
      }
    },
    cleanupTableData(data: any) {
      if (
        !(
          data.tables &&
          data.tables.length > 0 &&
          data.tables[0].hasOwnProperty('rows') &&
          data.tables[0].rows.length > 0
        )
      ) {
        return;
      }

      let columnDataStatusMap = new Map();

      // iterate table to check which column has data
      Array.from(data.tables[0].rows).forEach((row: any) => {
        Array.from(row.columns).forEach((column: any) => {
          if (column.is_extra_column) {
            if (columnDataStatusMap.has(column.name)) {
              if (columnDataStatusMap.get(column.name) === false) {
                if (column.formatted_value) {
                  columnDataStatusMap.set(column.name, true);
                }
              }
            } else {
              if (column.formatted_value) {
                columnDataStatusMap.set(column.name, true);
              } else {
                columnDataStatusMap.set(column.name, false);
              }
            }

            // delete column.is_extra_column;
          }
        });
      });

      // remove those column which do not have data and are marked as extra
      Array.from(data.tables[0].rows).forEach((row: any) => {
        row.columns = row.columns.filter((column: any) => {
          return !(
            columnDataStatusMap.has(column.name) &&
            columnDataStatusMap.get(column.name) === false
          );
        });
      });
    },
    triggerSaveData(e: any) {
      this.confirmationForSave();
    },
    confirmationForSave(moveToDashboard = false) {
      if (this.confirmationForPoConnectionReset) {
        this.moveToDashboard = moveToDashboard;
        this.showConfirmation = true;
      } else {
        this.decideNextOperation();
      }
    },

    proceedToSave() {
      this.record.po_multi_matched = [];
      this.decideNextOperation();
    },

    decideNextOperation() {
      this.confirmationForPoConnectionReset = false;
      if (this.isPoView) {
        this.viewPurchaseOrder();
      } else {
        this.saveData(this.moveToDashboard);
      }
    },

    async saveData(moveToDashboard: boolean) {
      const actionLockAcquired = await this.hasActionAcquiredLock();
      if (!actionLockAcquired) {
        return;
      }

      let data: any = this.record;
      this.showLoading();
      this.cleanupDataforApi(data);
      this.cleanupTableData(data);

      if (data.hasOwnProperty('table_data_copy')) {
        delete data['table_data_copy'];
      }

      let formData = new FormData();
      formData.append('data', JSON.stringify(this.record));
      formData.append('org_id', getOrgId());
      let response: any;
      try {
        let token: string = await getAuthorizationToken();
        response = await axios.post(api.save_document + this.docId, formData, {
          headers: {
            Authorization: token,
          },
        });

        this.hideLoading();

        if (response.data.success === false) {
          throw response;
        } else {
          notify.success(this.$t('MSG_SAVE'));
          if (moveToDashboard) {
            this.routeToDashboard();
          }
          const apiData = response.data.data;
          if (!apiData.hasOwnProperty('layout')) {
            apiData.layout = this.record.layout;
          }
          this.record = apiData;
          await this.removeCache();
          await this.setDataToCache();
        }
      } catch (err) {
        this.hideLoading();
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        return;
      }
    },
    routeToDashboard() {
      window.removeEventListener('beforeunload', this.onTabClose);
      this.releaseDocLock({ doc_id: this.record.doc_id });
      this.$router.push('/dashboard');
    },

    confirmationRuleSave() {
      if (!this.is_line_item_validated) {
        return;
      }
      this.confirmRuleSave = true;
    },

    async saveRules() {
      const actionLockAcquired = await this.hasActionAcquiredLock();
      if (!actionLockAcquired) {
        return;
      }
      let data: any = this.record;
      this.confirmRuleSave = false;
      this.showLoading();

      if (data.hasOwnProperty('table_data_copy')) {
        delete data['table_data_copy'];
      }
      let token: string = await getAuthorizationToken();
      let formData = new FormData();
      formData.append('data', JSON.stringify(data));
      formData.append('org_id', getOrgId());
      let response: any;
      try {
        response = await axios.post(api.save_rules, formData, {
          headers: {
            Authorization: token,
          },
        });

        this.hideLoading();
        if (response.data.success === false) {
          throw response;
        } else {
          notify.success(this.$t('MSG_SAVE'));
          this.$emit('autoDetectTables');
        }
      } catch (err) {
        this.hideLoading();
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        return;
      }
    },
    async validateConfigurationAndExport(routeType: number) {
      const actionLockAcquired = await this.hasActionAcquiredLock();
      if (!actionLockAcquired) {
        return;
      }

      this.exportData(routeType);
    },

    async exportData(routeType: number) {
      let data: any = this.record;
      this.cleanupDataforApi(data);
      this.cleanupTableData(data);

      // if PO enabled show warning messege
      if ((await this.isPoSettingActivate(this.doctype)) && !this.isPOView) {
        this.showPoMatchWarning = true;
        return;
      }

      this.showLoading();

      if (data.hasOwnProperty('table_data_copy')) {
        delete data['table_data_copy'];
      }

      let response: any;
      try {
        notify.dismissAll();
        let formData = new FormData();
        formData.append('data', JSON.stringify(data));
        response = await documentDetailApiService.validate_and_export(
          this.docId,
          formData,
        );

        if (response.success === true) {
          // if 0 only export and move to dashboard
          // else move to next invoice
          if (routeType === 0) {
            await this.dashboardFiltersAfterExport();
            this.routeToDashboard();
          } else {
            // api call to get next documnt id
            this.routeToNextInvoice(data.doc_type);
          }
          return;
        }

        let messages: [] = response.validation_error_codes;

        if (messages) {
          messages.forEach((messageStr: string) => {
            let temp = messageStr.split(':');
            let label = this.displayFieldLabel({
              translation_key: temp[0],
            });
            notify.error(
              label + ' ' + this.$t(temp[1]),
            );
          });
        } else {
          throw response;
        }

        this.$emit('setApiData', response.data);
        this.$emit('handleExportError');
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    async routeToNextInvoice(docType: string) {
      this.showLoading();
      let response: any;
      try {
        let token: string = await getAuthorizationToken();

        response = await axios.get(
          addOrgIdQueryString(
            api.get_next_document +
              this.docId +
              '?doc_type=' +
              docType +
              '&sort_attr=created_on',
          ),
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (response.data.success === true) {
          if (response.data.has_next === true) {
            notify.success(this.$t('NEXT_DOC_LOADED'));
            window.removeEventListener('beforeunload', this.onTabClose);
            this.$router.push('/field_validation_v1/' + response.data.next_id);
          } else {
            this.confirmRedirection = true;
          }
        } else {
          throw response;
        }
      } catch (err) {
        this.hideLoading();
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    viewPurchaseOrder() {
      this.isPoView = false;
      if (this.tb_version === null) {
        return;
      }

      this.decidePORoute();
    },

    navigateToPOMatch() {
      if (
        !this.validateLineItemTable(this.record.tables, this.record.doc_type)
      ) {
        return;
      }

      this.decidePORoute();
    },

    async decidePORoute() {
      const response: dynamicObj = await this.saveAndValidate();
      if (response.success === false) {
        const event = new CustomEvent('display_fields_errors', {});
        document.dispatchEvent(event);
        notify.error(response.message);
        return;
      }
      const po_match_route = await this.getPOUrl(this.record.doc_type);
      this.$router.push(po_match_route + this.record.doc_id);
    },

    onTabClose(e: any) {
      this.releaseDocLock({ doc_id: this.record.doc_id });

      let eventName = SessionStorage.has('event_name')
        ? (SessionStorage.getItem('event_name') as string)
        : null;
      if (eventName && eventName === 'language_change') {
        return;
      }
      e.preventDefault();
      e.returnValue = '';
      this.clearSelectedSessionStorage();
    },
    autoDetectTables() {
      this.$emit('autoDetectTables');
    },

    confirmAndExport() {
      if (!this.enableExportButton) {
        return;
      }

      this.validateConfigurationAndExport(0);
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const {
      record,
      tb_version,
      po_enable,
      doctype,
      language_origin,
      confirmationForPoConnectionReset,
      notifications,
      fieldErrors,
    } = storeToRefs(doc_store);
    const { saveAndValidate, setDataToCache, removeCache } = doc_store;

    const doc_lock_store = useDocLockStore();
    const { hasActionAcquiredLock, releaseDocLock } = doc_lock_store;

    const doc_line_items_store = useLineItemStore();
    const { validation_done } = storeToRefs(doc_line_items_store);

    const dashboard_store = useDashboardStore();
    const { dashboardFiltersAfterExport } = dashboard_store;

    return {
      fieldErrors,
      removeCache,
      setDataToCache,
      saveAndValidate,
      export_request_in_flight,
      dashboardFiltersAfterExport,
      is_line_item_validated: validation_done,
      record,
      doctype,
      language_origin,
      confirmationForPoConnectionReset,
      notifications,
      releaseDocLock,
      exportButtonWidth: ref('61'),
      confirmRuleSave: ref(false),
      po_enable,
      tb_version,
      hasActionAcquiredLock,
      confirmRedirection: ref(false),
    };
  },
});
</script>

<style scoped></style>
