<script lang="ts">
import axios from 'axios';
import { api } from 'pages/APIs';
import { storeToRefs } from 'pinia';
import cache from 'src/utils/cache';
import { Acl } from 'src/core/acls/index';
import { defineComponent, ref } from 'vue';
import { DOC2API_URL } from 'src/pages/APIs';
import Loader from '../components/Loader.vue';
import documentUtil from 'src/utils/documentUtil';
import { SessionStorage, debounce } from 'quasar';
import { readOnlyDocStatus } from 'src/constants';
import helperMixin from '../mixins/helperMixin.js';
import poActionsUtil from 'src/utils/poActionsUtil';
import { ApiExceptions } from 'src/exceptions/index';
import { setWithExpiry } from 'src/utils/cacheHelper';
import AIDialGauge from 'src/components/AIDialGauge.vue';
import autoTesting from 'src/components/autoTesting.vue';
import DocumentLock from 'src/components/DocumentLock.vue';
import { TableCoordinateType, dynamicObj } from './assets';
import { useImageAuth } from 'src/composables/useImageAuth';
import { authSdkService } from 'src/services/user/authSdkService';
import MessageBanner from 'src/components/MessageBanner.vue';
import { notify } from 'src/components/notifications/notify';
import invoiceSaveExport from 'pages/invoice-save-export.vue';
import Classification from 'src/components/Classification.vue';
import DeleteRulesBtn from 'src/components/DeleteRulesBtn.vue';
import LineItemsTblExtV3 from '../components/LineItemsTblExtV3.vue';
import scriptBtn from 'src/components/document/script/scriptBtn.vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import ErrorDocumentView from 'src/pages/Errors/ErrorDocumentView.vue';
import { cleanUpImagesUrl, cleanUpImagePath } from 'src/utils/viewImages';
import { getOrgId, addOrgIdQueryString} from 'src/utils/organization/org_id_helper';
import MultiSelectAreasImageTblV3 from '../components/MultiSelectAreasImageTblV3.vue';
import { useDocLockStore,useDocumentStore, useAuthTokenStore, useSettingStore, useUserStore} from 'src/store/main';
import IgnoreTableValidation from 'src/formBuilder/form_elements/components/ExtractedTableTabPanels/IgnoreTableValidation.vue';
let tableMap = new Map();

let tableData: TableCoordinateType = {
  columns: [],
  table_areas: [],
};

const $ = document.querySelector.bind(document);
let screenshot: HTMLElement;

const ZOOM_STEP = 100;
const MIN_IMAGE_WIDTH = 200;
// Upper bound relative to the width that fits #image_container, so the counter
// can never keep climbing past a width the image is actually rendered at.
const MAX_ZOOM_FACTOR = 5;

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, poActionsUtil, cache, documentUtil],
  components: {
    Loader,
    invoiceSaveExport,
    LineItemsTblExtV3,
    AIDialGauge,
    autoTesting,
    DocumentLock,
    MessageBanner,
    Classification,
    DeleteRulesBtn,
    ErrorDocumentView,
    MultiSelectAreasImageTblV3,
    scriptBtn,
    SubHeader,
    IgnoreTableValidation,
    
  },
  data() {
    return {
      draggingColumnEl: {} as any,
      deleteColumnInfo: {} as any,
      enableEditing: false,
      enableColumnEditing: false,
      imageHeight: 0,
      imageWidth: 0,
      fitImageWidth: 0,
      enableExportButton: false,
      account_block: '',
      extractedData: '',
      currentColumnName: '',
      currentRowId: '',
      debounceAutoSaveFunc: {} as any,
    };
  },
  watch: {
    training_mode(val) {
      if (val === false) {
        this.persistTableAreas();
        this.restrictDrawing();
        this.setTableMode();
      }
    },

    $route(to, from) {
      if (!to.hasOwnProperty('path') || !from.hasOwnProperty('path')) {
        return;
      }

      const to_route = to.path.split('/');
      const from_route = from.path.split('/');
      // match for same route name
      if (
        to_route.length > 2 &&
        from_route.length > 2 &&
        to_route[1] === from_route[1] &&
        this.get_cached_data_id != this.docId
      ) {
        window.location.reload();
      }
    },
  },
  mounted() {
    this.init();
    this.isDebugFlagHandler();
    document.addEventListener('update_table_data', this.updateTableDataForSave);
    document.addEventListener(
      'delete_select_area_column',
      this.deleteColumnDataForReSelection,
    );
    document.addEventListener(
      'validate_selected_column',
      this.validateSelectedColumn,
    );
    document.addEventListener('disable_all_modes', this.diableAllModes);
    document.addEventListener('rules_deleted', this.rulesDeleted);
    document.addEventListener('perform_split_text', this.callSplitTextAction);
    (<any>window).tblExtV3 = this;
    this.debounceAutoSaveFunc = debounce(() => {
      this.saveDataOnChanges();
    }, 1000);
  },
  unmounted: function () {
    window.removeEventListener('resize', this.windowResize);
    document.removeEventListener(
      'update_table_data',
      this.updateTableDataForSave,
    );
    document.removeEventListener(
      'delete_select_area_column',
      this.deleteColumnDataForReSelection,
    );
    document.removeEventListener(
      'validate_selected_column',
      this.validateSelectedColumn,
    );
    document.removeEventListener('disable_all_modes', this.diableAllModes);
    document.removeEventListener('rules_deleted', this.rulesDeleted);
    document.removeEventListener('rules_deleted', this.rulesDeleted);
    document.removeEventListener(
      'perform_split_text',
      this.callSplitTextAction,
    );
    this.clearViewForUnmount();
  },
  computed: {
    // Query string appended to the document image / crop URLs.
    //
    // In the external table_train_v3 deep-link flow the SDK auth store is never
    // populated. useImageAuth's async onMounted refresh resolves to an empty
    // token AFTER the page has seeded the URL token, clobbering tokenQueryParam
    // back to '' — so the images were requested credential-less (`.../1.jpg?`)
    // and the resource route rejected them with 422. Derive the query directly
    // from the URL token instead: deterministic and immune to that race. org_id
    // is omitted on purpose — the resource route derives the org from the
    // (org-scoped) token. The normal (logged-in) flow keeps using the composable
    // token, which carries a valid org.
    imageAuthQuery() {
      if (this.table_train) {
        const urlToken = String(this.$route.query.token || '');
        return urlToken ? `token=${urlToken}` : '';
      }
      return this.tokenQueryParam;
    },
  },
  methods: {
    async init() {
      this.isDocForTraining();
      await this.handleTokenForExternalUser();

      if (this.table_train === true) {
        this.setDocLockStoreDisable();
        this.docId = String(this.$route.query.id);
        await this.getTrainingData();
        if (
          !this.record ||
          Object.keys(this.record).length === 0 ||
          this.record.success === false
        ) {
          this.handleException();
          return;
        }
      } else {
        this.docId = String(this.$route.params.id);

        if (!this.$route.params.id) {
          this.$router.push('/dashboard');
        }

        await this.getInvoiceDataByDocId();
        if (
          !this.record ||
          Object.keys(this.record).length === 0 ||
          this.record.success === false
        ) {
          this.handleException();
          return;
        }

        this.setTableTrainingFlag();
        const event = new CustomEvent('init_line_items', {
          detail: this.record,
        });
        document.dispatchEvent(event);
      }

      this.handleBlockedSupplier();
      if (this.account_block) {
        return;
      }

      window.addEventListener('resize', this.windowResize);
      this.handleAiTableWarning();
      this.handleReadOnly();
      this.handleDocLockSubscribe();
      if (this.isReadOnly) {
        this.error_message = this.$t('READ_ONLY_MSG');
        this.trigger_document_lock = false;
      } else {
        this.trigger_document_lock = true;
      }

      this.imageWidth =
        ($('#image_container') as HTMLElement)!.offsetWidth - 15;
      this.fitImageWidth = this.imageWidth;
      SessionStorage.set('table_data', '');
      SessionStorage.set('table_rows_data', '');
      this.initPage();
    },

    async handleTokenForExternalUser() {
      const token = this.table_train === true ? String(this.$route.query.token) : '';
      await this.setAuthToken(token);
      if (this.table_train) {
        this.ignore_token_validation = true;
      }
      this.getTokenQueryParam();
      await this.loadProfileForUrlToken();
    },

    // Deep-link flow only (no logged-in session, so no user_details). Same pair
    // as PrepareDashboard step 1: getProfile() sets user_details.id, and
    // setUserSession() is what persists org_id — the profile response has none.
    async loadProfileForUrlToken() {
      if (!this.$route.query.token) {
        return;
      }

      try {
        await this.getProfile();
        await authSdkService.setUserSession();
      } catch (err) {
        // Non-fatal: the screen rendered without a profile before this existed.
        logError(err);
      }
    },

    restoreDeleteColumn() {
      if (this.isReadOnly) {
        return;
      }
      const event = new CustomEvent('restore_delete_column', {
        detail: { restore_table_columns: true },
      });
      document.dispatchEvent(event);
    },

    handleAiTableWarning() {
      if (!this.has_ai_table) {
        return;
      }
      this.ai_table_warning = true;
    },

    handleException() {
      this.isReadOnly = true;
      this.error_message = this.$t('INVALID_DOCUMENT');
      this.bannerBg = 'error-banner';
    },

    doManualTraining() {
      if (this.ai_table_warning) {
        this.ai_table_warning = false;
        this.deleteAllExtractedData();
        this.setManualTraining(true);
      }
    },

    handleDocLockSubscribe() {
      const doc_lock_store = useDocLockStore();
      doc_lock_store.$subscribe((mutation, state) => {
        this.isReadOnly = !this.doc_lock?.success;
        this.handleReadOnly();
      });
    },

    handleReadOnly() {
      if (readOnlyDocStatus.includes(this.record.status)) {
        this.isReadOnly = true;
        return;
      }

      // check for access - pass the document to check permissions based on doc_type
      if (!Acl.canUpdate(this.record)) {
        this.isReadOnly = true;
      }
    },

    isDocForTraining() {
      if (
        this.$route.params.table_train &&
        this.$route.params.table_train === 'true'
      ) {
        this.table_train = true;
      }
    },

    setTableTrainingFlag() {
      if (this.table_train === true) {
        this.record.is_table_training_doc = true;
      }
    },

    getToken() {
      return this.token;
    },

    async getTrainingData() {
      try {
        let response: any;
        response = await this.getTrainingDataByDocId();

        if (!response || !response.data) {
          throw response;
        }

        if (response.data.success === false && this.api_tries < 1) {
          // call onces more
          this.api_tries++;
          response = await this.getTrainingDataByDocId();
        }

        if (
          response.data.success === false ||
          !response.data.data ||
          !response.data.data.doc_id
        ) {
          throw response;
        }

        this.record = response.data.data;
        this.record.token = this.token;
        this.is_manual_training_allowed = true;
        this.setTableTrainingFlag();
        const event = new CustomEvent('init_line_items', {
          detail: this.record,
        });
        document.dispatchEvent(event);
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async getTrainingDataByDocId() {
      this.showLoading();
      let response: any;
      try {
        let token: string = this.getToken();
        response = await axios.get(
          addOrgIdQueryString(
            api.get_table_train_data + this.docId + '&version=v3',
          ),
          {
            headers: {
              Authorization: token,
            },
          },
        );
      } catch (err) {
        logError(err);
      }
      return response as dynamicObj;
    },

    async getInvoiceDataByDocId() {
      try {
        if (this.record.doc_id == this.docId) {
          return;
        }
        this.showLoading();
        this.record = [];
        this.clearSelectedSessionStorage();
        const data = {
          doc_id: this.docId,
        };
        await this.getDocumentById(this.docId);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    initPage() {
      this.page = 1;
      this.handleImageBaseURL();
      this.image =
        this.baseUrl + '/' + cleanUpImagePath(this.record.images[0].path);
      this.images = cleanUpImagesUrl(this.record.images);
      SessionStorage.set('table_data', '');
      tableMap = new Map();
      if (
        this.record.tables &&
        this.record.tables[0] &&
        this.record.tables[0].locations_list &&
        this.record.tables[0].locations_list[0]
      ) {
        this.prepareTableMap(this.record.tables[0].locations_list);
      }
      this.document_version = !this.record.document_version
        ? 1
        : this.record.document_version;

      window.addEventListener('keydown', (e: any) => {
        if (e.keyCode === 27) {
          this.restrictDrawing();
        }
      });

      if (SessionStorage.has('enableExportButton')) {
        this.enableExportButton = SessionStorage.getItem('enableExportButton')!;
      } else {
        this.enableExportButton = false;
      }
      this.$forceUpdate();

      this.setTableVersion();
      this.getAI_IndicatorData();
      this.getExtractedColumns();
      this.fetchLanguageOptions();
      this.confirmationForPoConnectionReset = false;
    },

    async setTableVersion() {
      let TBL_EXT_VERSION = await this.getSetting('TBL_EXT_VERSION');

      if (!this.record.tables || this.record.tables.length == 0) {
        if (
          TBL_EXT_VERSION !== undefined &&
          TBL_EXT_VERSION != '' &&
          TBL_EXT_VERSION == 'Version3'
        ) {
          this.tb_version = 'v3';
        }
        return;
      }

      if (
        this.record.tables[0].hasOwnProperty('version') &&
        this.record.tables[0].version == 'v3'
      ) {
        this.tb_version = 'v3';
      }

      this.setPoMatchingData();
    },

    async getAI_IndicatorData() {
      try {
        this.setTableCountForAIIndicator();
        let response: any;
        if (
          !this.record.filter_values ||
          !(this.record.filter_values.length > 0) ||
          !Array.isArray(this.record.filter_values)
        ) {
          throw 'getAI_IndicatorData () no filter_values or doc_type to proceed';
        }
        let query =
          '?doc_type=' +
          this.record.doc_type +
          '&filter_values=' +
          this.record.filter_values.join();
        let token: string = this.getToken();
        let formData = new FormData();
        formData.append('org_id', getOrgId());
        response = await axios.post(api.get_ai_score + query, formData, {
          headers: {
            Authorization: token,
          },
        });

        if (response.data.success === false) {
          throw response.data.message;
        }

        if (response.data.success === true) {
          this.ai_rules = response.data.table_rules;
          const event = new CustomEvent('TE_gauge_calculation', {
            detail: response.data,
          });
          document.dispatchEvent(event);
        }
      } catch (err) {
        logError(err);
      }
    },

    setTableCountForAIIndicator() {
      let tables = 0;

      if (
        this.record &&
        this.record.tables &&
        Array.isArray(this.record.tables) &&
        this.record.tables.length > 0 &&
        this.record.tables[0].hasOwnProperty('rows') &&
        Array.isArray(this.record.tables[0].rows) &&
        this.record.tables[0].rows.length > 0
      ) {
        tables = 1;
      }
      this.ai_tables = tables;
    },

    setPoMatchingData() {
      const event = new CustomEvent('po_info', {
        detail: { tb_version: this.tb_version, po_enable: this.po_enable },
      });
      document.dispatchEvent(event);
    },

    handleBlockedSupplier() {
      this.account_block = '';

      if (
        this.record.hasOwnProperty('table_blocked') &&
        (this.record.table_blocked == true ||
          this.record.table_blocked == 'true')
      ) {
        this.account_block = 'table_blocked';
      }

      if (
        this.record.hasOwnProperty('table_extraction_disabled') &&
        (this.record.table_extraction_disabled == true ||
          this.record.table_extraction_disabled == 'true')
      ) {
        this.account_block = 'table_extraction_disabled';
      }

      if (
        this.record.hasOwnProperty('table_not_supported') &&
        (this.record.table_not_supported == true ||
          this.record.table_not_supported == 'true')
      ) {
        this.account_block = 'table_not_supported';
      }

      if (this.record.extraction_method == 'ELECTRONIC_DOCUMENT') {
        this.account_block = 'table_extraction_disabled';
      }
    },

    toggler() {
      this.toggleMenu();
      this.windowResize();
    },

    back() {
      if (
        this.record.hasOwnProperty('has_layout') &&
        String(this.record.has_layout) === 'true'
      ) {
        this.$router.push('/field_validation_v1/' + this.$route.params.id);
        return;
      }
    },

    imageClicked(evt: any) {
      this.loadNewPageImage(evt.target.dataset.id);
    },

    loadNewPageImage(pageNumber: any) {
      this.persistTableAreas();
      this.image =
        this.baseUrl +
        '/' +
        cleanUpImagePath(this.record.images[pageNumber].path);
      this.page = parseInt(pageNumber) + 1;

      if (this.isRowMode === true) {
        setTimeout(() => {
          const event = new CustomEvent('get_table_rows_areas', {});
          document.dispatchEvent(event);
        }, 10);
      } else {
        this.loadNewPageTableAreas();
      }
      this.resizeSelectableColumns();
      this.$forceUpdate();
    },

    persistTableAreas() {
      if (
        SessionStorage.has('table_data') &&
        SessionStorage.getItem('table_data') != null &&
        SessionStorage.getItem('table_data') != ''
      ) {
        let tableDataStr = SessionStorage.getItem('table_data');
        tableData = JSON.parse(tableDataStr as string);
        if (
          tableData &&
          tableData.table_areas &&
          tableData.table_areas.length
        ) {
          tableMap.set(this.page.toString(), JSON.stringify(tableData));
        } else {
          tableMap.delete(this.page.toString());
        }
      } else {
        tableMap.delete(this.page.toString());
      }
    },

    loadNewPageTableAreas() {
      if (tableMap.has(this.page.toString())) {
        tableData = JSON.parse(tableMap.get(this.page.toString()));
      } else {
        tableData = { columns: [], table_areas: [] };
      }

      this.tableAreasStr = JSON.stringify(tableData);
      SessionStorage.set('table_data', this.tableAreasStr);
    },

    prepareTableMap(tableJson: any) {
      tableMap = new Map();
      if (tableJson) {
        Array.from(tableJson).forEach((data: any) => {
          if (data) {
            let tableDetails: TableCoordinateType = {
              columns: [],
              table_areas: data.coords,
            };
            tableMap.set(data.page.toString(), JSON.stringify(tableDetails));
          }
        });
      }
      this.loadNewPageTableAreas();
    },
    /**
     * Will allow user to draw rectangles on image when user reject div overlay
     */
    enableDrawing() {
      this.enableEditing = true;
      const draw: HTMLElement | null = $('#draw');
      draw?.classList.add('cursor-crosshair');
      draw?.classList.remove('pointer-events-none');
      this.disableColumnEditing();
      this.setTableMode();
    },
    /**
     * Will restrict user to draw rectangles on image
     */
    restrictDrawing() {
      this.enableEditing = false;
      const draw: HTMLElement | null = $('#draw');
      draw?.classList.add('pointer-events-none');
      draw?.classList.remove('cursor-crosshair');
    },

    windowResize() {
      this.persistTableAreas();
      let imageElm = $('#image_container') as HTMLElement;
      this.imageWidth = imageElm.offsetWidth;
      this.fitImageWidth = this.imageWidth;

      setTimeout(() => {
        screenshot = $('#screenshot') as HTMLElement;
        if (screenshot) {
          this.imageHeight = screenshot.offsetHeight;
        }
        this.$forceUpdate();
        this.resizeSelectableColumns();
      }, 10);
    },

    resizeSelectableColumns() {
      let columns = document.querySelectorAll<HTMLElement>('.draggable-column');
      for (var i = 0; i < columns.length; i++) {
        let column = columns[i];
        let normalized_value = column.dataset.normalized_value;
        let left = +normalized_value! * this.imageWidth;

        if (
          this.page == Number(column.dataset.page_no) ||
          column.dataset.page_no == 'all'
        ) {
          column.style.display = 'block';
          column.style.left = left.toString() + 'px';
          column.style.height = String(this.imageHeight) + 'px';
        } else {
          column.style.display = 'none';
        }
      }
    },

    // Copy current page columns for all others
    addColumnForAll(event: any) {
      event.stopPropagation();
      const columnList =
        document.querySelectorAll<HTMLElement>('.draggable-column');
      // if page no is all then keep it
      if (columnList.length == 0) {
        notify.error('No column detected');
        return;
      }
      for (var i = 0; i < columnList.length; i++) {
        let column = columnList[i];
        if (
          column.dataset.page_no !== this.page.toString() &&
          column.dataset.page_no !== 'all'
        ) {
          column.remove();
          continue;
        }

        let normalized_value = column.dataset.normalized_value;
        let left = +normalized_value! * this.imageWidth;

        column.style.left = left.toString() + 'px';
        column.dataset.page_no = 'all';
        column.style.display = 'block';
      }
    },

    disableColumnEditing() {
      this.enableColumnEditing = false;
      this.draggingColumnEl = null;
      this.deleteColumnInfo = null;
      document.removeEventListener('pointermove', this.repositionColumn);
      document.removeEventListener('pointerup', this.columnStopDrag);
    },

    reDrawColumns(columnsArray: any, page_no: string) {
      if (!columnsArray || columnsArray.length < 1) {
        return;
      }

      this.deleteColumnInfo = null;
      this.persistTableAreas();
      this.restrictDrawing();
      this.setTableMode();
      let imageElm = $('#screenshot_container') as HTMLElement;

      screenshot = $('#screenshot') as HTMLElement;
      this.imageWidth = screenshot.offsetWidth;
      this.imageHeight = screenshot.offsetHeight;

      Array.from(columnsArray).forEach((columnCoord: any) => {
        let left = +columnCoord * this.imageWidth;
        // draggable column
        var parent = document.createElement('div');
        parent.className = 'draggable-column';
        parent.style.height = String(this.imageHeight) + 'px';
        parent.style.left = left.toString() + 'px';
        parent.dataset.parent_class = 'screenshot';
        parent.dataset.page_no = page_no.toString();
        parent.dataset.normalized_value = columnCoord; //(left / this.imageWidth).toString();

        imageElm.appendChild(parent);
        // events for dragging
        parent.addEventListener(
          'pointerdown',
          this.pointerDownDraggableColumn,
          false,
        );
      });
    },

    addColumn(event: any) {
      this.enableColumnEditing = true;
      this.deleteColumnInfo = null;
      this.persistTableAreas();
      this.restrictDrawing();
      this.setTableMode();
      event.stopPropagation();
      let imageElm = $('#screenshot_container') as HTMLElement;

      screenshot = $('#screenshot') as HTMLElement;
      this.imageWidth = screenshot.offsetWidth;
      this.imageHeight = screenshot.offsetHeight;

      let left = this.getNewColPosOffset(this.page);

      // draggable column
      var parent = document.createElement('div');
      parent.className = 'draggable-column';
      parent.style.height = String(this.imageHeight) + 'px';
      parent.style.left = left.toString() + 'px';
      parent.dataset.parent_class = 'screenshot';
      parent.dataset.page_no =
        event.page !== undefined ? event.page : this.page.toString();

      parent.dataset.normalized_value = (left / this.imageWidth).toString();

      imageElm.appendChild(parent);
      // events for dragging
      parent.addEventListener(
        'pointerdown',
        this.pointerDownDraggableColumn,
        false,
      );
    },

    getNewColPosOffset(page: number) {
      let prevColPos = 0,
        newOffset = 0;
      const screenshot = $('#screenshot') as HTMLElement;
      const columnList =
        document.querySelectorAll<HTMLElement>('.draggable-column');
      const divWidth = screenshot.offsetWidth - screenshot.offsetLeft;

      if (columnList.length) {
        let firstColumn = null;
        for (var i = 0; i < columnList.length; i++) {
          let column = columnList[i];
          if (
            page == Number(column.dataset.page_no) ||
            column.dataset.page_no == 'all'
          ) {
            firstColumn = column;
          }
        }
        if (firstColumn) {
          prevColPos = parseInt(firstColumn.style.left);
        }
      }

      if (prevColPos + 25 > divWidth) {
        prevColPos = 0;
      }

      newOffset = prevColPos + 25;
      return newOffset;
    },

    removeDraggableColumn(event: any) {
      this.draggingColumnEl = null;
      this.deleteColumnInfo = null;
      event.target.remove();
    },

    pointerDownDraggableColumn(event: any) {
      event.preventDefault();
      event.target.clicks++;

      setTimeout(function () {
        event.target.clicks = 0;
      }, 400);

      if (event.target.clicks === 2) {
        this.removeDraggableColumn(event);
        event.target.clicks = 0;
        return;
      }
      this.columnDragStart(event);
    },

    columnDragStart(event: any) {
      let initX = event.target.offsetLeft;
      let initY = event.target.offsetTop;
      let mousePressX = event.clientX;
      let mousePressY = event.clientY;
      this.draggingColumnEl = {
        el: event.target,
        initX,
        initY,
        mousePressX,
        mousePressY,
      };

      this.deleteColumnInfo = {
        event: event,
      };
      document.addEventListener('pointermove', this.repositionColumn, false);
      document.addEventListener('pointerup', this.columnStopDrag, false);
    },

    columnStopDrag(event: any) {
      this.draggingColumnEl = null;
      let imageElm = $('#image_container') as HTMLElement;
      if (!imageElm) {
        return;
      }
      let columns = imageElm.querySelectorAll<HTMLElement>('.draggable-column');
      for (var i = 0; i < columns.length; i++) {
        columns[i].removeEventListener(
          'pointermove',
          this.repositionColumn,
          false,
        );

        let left = columns[i].style.left.replace('px', '');
        columns[i].dataset.normalized_value = (
          +left / this.imageWidth
        ).toString();
      }
    },

    repositionColumn(event: any) {
      if (
        !(
          this.draggingColumnEl &&
          this.draggingColumnEl.initX &&
          this.draggingColumnEl.mousePressX
        )
      ) {
        return;
      }

      let parent_class = this.draggingColumnEl.el.dataset.parent_class;
      let parent = $('#' + parent_class) as HTMLElement;
      if (!parent) {
        logInfo('column parent id is missing');
        return;
      }
      this.deleteColumnInfo = null;
      var parentRect = parent.getBoundingClientRect();
      if (event.clientX >= parentRect.left) {
        // within boundries
        this.draggingColumnEl.el.style.left =
          this.draggingColumnEl.initX +
          event.clientX -
          this.draggingColumnEl.mousePressX +
          'px';
        return;
      }
      // out of boundries
      this.draggingColumnEl.el.style.left =
        Math.floor((5 * parent.offsetWidth) / 100) + 'px';
    },

    removeAllColumns() {
      this.deleteColumnInfo = null;
      this.draggingColumnEl = null;
      const columnList =
        document.querySelectorAll<HTMLElement>('.draggable-column');
      if (columnList.length == 0) {
        return;
      }
      for (var i = 0; i < columnList.length; i++) {
        columnList[i].remove();
      }
    },

    isColumnSelectedForDelete() {
      if (
        !this.deleteColumnInfo ||
        Object.keys(this.deleteColumnInfo).length === 0 ||
        !this.deleteColumnInfo.event
      ) {
        return false;
      }
      return true;
    },

    removeSelectedColumn(e: any) {
      if (
        !this.deleteColumnInfo ||
        Object.keys(this.deleteColumnInfo).length === 0 ||
        !this.deleteColumnInfo.event
      ) {
        this.deleteColumnInfo = null;
        return;
      }
      this.removeDraggableColumn(this.deleteColumnInfo.event);
      this.deleteColumnInfo = null;
    },

    getExtractedColumns() {
      this.extracted_columns = [];
      if (
        !(
          this.record &&
          this.record.tables &&
          this.record.tables.length > 0 &&
          this.record.tables[0].hasOwnProperty('extraction_info') &&
          this.record.tables[0].extraction_info.length > 0
        )
      ) {
        return;
      }
      Array.from(this.record.tables[0].extraction_info).forEach(
        (pageInfo: any) => {
          if (pageInfo.hasOwnProperty('columns')) {
            let columns = [] as string[];
            Array.from(pageInfo.columns).forEach((value: any) => {
              columns = columns.concat(value.toString().split(','));
            });

            this.extracted_columns['page_' + pageInfo.page] = columns;
          }
        },
      );
    },

    toggleExtractedColumnMode(showErrorToast: boolean) {
      this.isExtractedColumnMode = true;
      this.enableColumnEditing = true;
      this.showExtractedColumns(showErrorToast);
      this.resizeSelectableColumns();
      this.isExtractedColumnMode = false;
    },

    showExtractedColumns(showErrorToast: boolean) {
      if (
        (!this.extracted_columns ||
          Object.keys(this.extracted_columns).length === 0) &&
        showErrorToast
      ) {
        notify.error(this.$t('NO_COLUMNS_FOUND'));
        return;
      }

      this.removeAllColumns();

      for (let i = 0; i <= this.images.length; i++) {
        if (this.extracted_columns.hasOwnProperty('page_' + i)) {
          this.reDrawColumns(this.extracted_columns['page_' + i], i.toString());
        }
      }
    },

    async saveTableCoordinates(paramName = '') {
      try {
        this.showLoading();
        this.persistTableAreas();
        this.setRulesForSelectableColumns();

        let tableCordJson: any = [];

        tableMap.forEach((value: string, key: string) => {
          if (value && key) {
            tableData = JSON.parse(value);

            tableCordJson.push(
              Object.assign(
                {},
                {
                  page: key,
                  table_areas: tableData.table_areas,
                  columns: tableData.columns,
                },
              ),
            );
          }
        });
        let formData = new FormData();

        formData.append('doc_id', this.record.doc_id as string);
        formData.append('table_extraction_data', JSON.stringify(tableCordJson));
        formData.append('header_rows_count', '1');

        let get_mapping_rules = this.addMappingFlag();
        if (get_mapping_rules !== '') {
          formData.append('get_mapping_rules', get_mapping_rules.toString());
        }

        if (paramName === 'add_split_text') {
          formData.append('split_text', this.split_text.toString());
        }

        if (paramName === 'doc_locale') {
          formData.append('doc_locale', this.languageOrigin);
        }

        if (this.record.hasOwnProperty('is_table_training_doc')) {
          formData.append('is_table_training_doc', true.toString());
        }

        if (this.force_ocr_table_train) {
          formData.append('force_ocr', true.toString());
        }
        this.force_ocr_table_train = false;

        formData.append('org_id', getOrgId());
        let response: any;
        let token: string = this.getToken();
        response = await axios.post(api.get_table_v3, formData, {
          headers: {
            Authorization: token,
          },
        });

        if (
          !response.data ||
          !Array.isArray(response.data) ||
          response.data.length == 0
        ) {
          throw {
            message: this.$t('CANNOT_EXECUTE_REQUEST'),
          };
        }

        if (response.data[0].success === false) {
          throw {
            message: response.data[0].message,
          };
        }
        this.setApiResponse(response);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    setApiResponse(response: any) {
      if (response.data && response.data[0].hasOwnProperty('locations_list')) {
        this.record.tables = response.data;
        this.setTableCountForAIIndicator();
        this.prepareTableMap(this.record.tables[0].locations_list);
        this.getExtractedColumns();
        this.restrictDrawing();
        this.disableColumnEditing();
        this.setTableMode();
        this.resetLineItems();
      }
    },

    setRulesForSelectableColumns() {
      let columnSeparators =
        document.querySelectorAll<HTMLElement>('.draggable-column');
      if (!columnSeparators) {
        return;
      }
      let parent = $('#screenshot') as HTMLElement;
      if (!parent) {
        return;
      }
      let parentOffsetWidth = parent.offsetWidth;
      for (var j = 0; j < this.images.length; j++) {
        let image_page = (j + 1).toString();
        let selectedSeparators = [];
        for (var i = 0; i < columnSeparators.length; i++) {
          let column = columnSeparators[i];
          if (
            image_page == column.dataset.page_no ||
            column.dataset.page_no == 'all'
          ) {
            let left = column.style.left.replace('px', '');
            selectedSeparators.push(+left / parentOffsetWidth);
          }
        }
        if (selectedSeparators.length > 0) {
          selectedSeparators = this.sortNumbericArray(selectedSeparators);
          this.addColumnsToTableMap(selectedSeparators, image_page);
        }
      }
    },

    addColumnsToTableMap(selectedSeparators: any, image_page: string) {
      let table: { [k: string]: any } = {};
      table.table_areas = [];
      if (tableMap.has(image_page)) {
        table = JSON.parse(tableMap.get(image_page));
      }
      table.columns = [selectedSeparators.toString()];
      tableMap.set(image_page, JSON.stringify(table));
    },

    async autoDetectTables() {
      this.showLoading();

      let formData = new FormData();

      formData.append('doc_id', this.record.doc_id as string);
      formData.append('extract_ai_table', true.toString());
      if (this.record.hasOwnProperty('is_table_training_doc')) {
        formData.append('is_table_training_doc', true.toString());
      }

      let response: any;
      try {
        formData.append('org_id', getOrgId());
        let token: string = this.getToken();
        response = await axios.post(api.get_auto_table_v3, formData, {
          headers: {
            Authorization: token,
          },
        });

        if (response.data.success === false) {
          throw response;
        }

        this.setApiResponse(response);
        this.hideLoading();
        //restore columns
        this.toggleExtractedColumnMode(false);
      } catch (err) {
        this.hideLoading();
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    deleteAllExtractedData() {
      this.isExtractedColumnMode = false;
      this.extracted_columns = [];
      tableMap = new Map();
      tableData = { columns: [], table_areas: [] };

      this.record.tables = null;
      this.setTableCountForAIIndicator();
      this.restrictDrawing();
      this.removeAllColumns();
      tableData = { columns: [], table_areas: [] };
      this.tableAreasStr = JSON.stringify(tableData);
      SessionStorage.set('table_data', this.tableAreasStr);

      const event = new CustomEvent('reset_table_areas', {
        detail: this.record,
      });
      document.dispatchEvent(event);

      this.resetLineItems();
      this.$forceUpdate();
    },

    currentPage() {
      return this.page;
    },

    diableAllModes() {
      this.persistTableAreas();
      this.restrictDrawing();
      this.setTableMode();
    },

    updateExtractionDataForSave(indexName: string, data: any) {
      if (
        !this.record ||
        !this.record.tables ||
        !this.record.tables[0] ||
        !this.record.tables[0].hasOwnProperty('extraction_info')
      ) {
        return;
      }

      for (let [key, value] of Object.entries(
        this.record.tables[0].locations_list,
      )) {
        this.record.tables[0].locations_list[key][indexName] = data;
      }
    },

    updateTableDataForSave(e: any) {
      if (!e || !e.detail || !this.record || !this.record.tables) {
        return;
      }

      this.record.tables = e.detail.tables;
      this.setTableCountForAIIndicator();
      if (e.detail.save_to_server && e.detail.save_to_server === true) {
        this.debounceAutoSaveFunc();
      }
    },

    resetLineItems() {
      const event = new CustomEvent('init_line_items', { detail: this.record });
      document.dispatchEvent(event);
    },

    openLineItemAdvanceSettings() {
      this.restrictDrawing();
      const event = new CustomEvent('display_adv_settings_view', {});
      document.dispatchEvent(event);
    },

    addColumnInLineItems() {
      this.diableAllModes();
      const event = new CustomEvent('add_new_column', {});
      document.dispatchEvent(event);
    },

    setApiData(data: any) {
      this.record = data;
      this.$forceUpdate();
    },

    setFieldsData(data: any) {
      this.record.document_version = data.document_version;
      this.record.fields = data.fields;
      this.record.tables = data.tables;
      this.$forceUpdate();
    },

    revertChanges() {
      const event = new CustomEvent('revert_changes', {});
      document.dispatchEvent(event);
    },

    handleImageBaseURL() {
      if (!this.record.images[0]) {
        return;
      }
      if (this.record.images[0].path.match(/doc2/g)) {
        this.baseUrl = DOC2API_URL;
      }
    },

    maxImageWidth() {
      const fit = this.fitImageWidth || this.imageWidth;
      return Math.max(fit * MAX_ZOOM_FACTOR, MIN_IMAGE_WIDTH);
    },

    applyZoom(delta: number) {
      const next = Math.min(
        Math.max(this.imageWidth + delta, MIN_IMAGE_WIDTH),
        this.maxImageWidth(),
      );
      if (next === this.imageWidth) {
        return;
      }
      this.imageWidth = next;
      screenshot = $('#screenshot') as HTMLElement;
      setTimeout(() => {
        this.imageHeight = screenshot.offsetHeight;
        this.resizeSelectableColumns();
      }, 10);
    },

    zoomOut() {
      this.applyZoom(-ZOOM_STEP);
    },

    zoomIn() {
      this.applyZoom(ZOOM_STEP);
    },

    addNewLineItem() {
      const event = new CustomEvent('add_new_row', {});
      document.dispatchEvent(event);
    },

    setTableRowCorrdinates(
      tableRowCorrd: string,
      columnName: any,
      rowId: string,
    ) {
      tableData = { columns: [], table_areas: [] };

      this.currentRowId = rowId;
      this.currentColumnName = columnName;
      tableData.table_areas = JSON.parse(tableRowCorrd);

      this.tableAreasStr = JSON.stringify(tableData);
      SessionStorage.set('table_rows_data', this.tableAreasStr);
      this.$forceUpdate();
    },

    setRowMode() {
      if (this.isRowMode === true) {
        this.persistTableAreas();
        this.restrictDrawing();
        this.disableColumnEditing();
        // event to get all the rows on the same page
        const event = new CustomEvent('get_table_rows_areas', {});
        document.dispatchEvent(event);
      } else {
        this.setTableMode(false);
      }
    },

    setTableMode(setFlag = true as boolean) {
      if (setFlag === true) {
        this.isRowMode = false;
      }

      this.loadNewPageTableAreas();
    },

    async saveColumnCoords(columnCoordStr: string) {
      if (!this.currentColumnName || !columnCoordStr) {
        notify.error(
          this.$t('Please Select Line Column and then try again'),
        );
        return;
      }

      this.showLoading();

      let tableRect = [];
      tableRect = columnCoordStr.split(',');

      let formData = new FormData();
      formData.append('x0', tableRect[0].toString());
      formData.append('y0', tableRect[1].toString());
      formData.append('x1', tableRect[2].toString());
      formData.append('y1', tableRect[3].toString());
      formData.append('doc_id', this.record.doc_id);
      formData.append('page', this.page.toString());
      formData.append('column_name', this.currentColumnName);
      formData.append('table_name', this.record.tables[0].name);

      if (this.record.hasOwnProperty('is_table_training_doc')) {
        formData.append('is_table_training_doc', true.toString());
      }

      let response: any;
      try {
        formData.append('org_id', getOrgId());
        let token: string = this.getToken();
        response = await axios.post(api.get_table_text, formData, {
          headers: {
            Authorization: token,
          },
        });
      } catch (err) {
        this.hideLoading();
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }

      const coords = response.data.coords;

      if (
        !coords ||
        (coords[0].x === 0 &&
          coords[0].y === 0 &&
          response.data.formatted_value === '')
      ) {
        notify.error(
          this.$t('EMPTY_MAPPING_NOT_ALLOWED'),
        );
        this.hideLoading();
        return;
      }
      this.updateApiForTableColumn(response.data);

      const event = new CustomEvent('init_line_items', { detail: this.record });
      document.dispatchEvent(event);

      // wait until data is re-populated
      setTimeout(() => {
        // get the item into view
        let selectedInput = $(
          '#' + 'input_' + this.currentColumnName + '_' + this.currentRowId,
        ) as HTMLElement;
        if (selectedInput) {
          selectedInput.scrollIntoView();
          selectedInput
            .querySelector('label')!
            .classList.add('active-border-2px');
        }
      }, 30);

      this.$forceUpdate();
      this.hideLoading();
    },

    updateApiForTableColumn(columnExtratedData: any) {
      Array.from(this.record.tables[0].rows).forEach(
        (row: any, rowIndex: any) => {
          if (row.id === this.currentRowId) {
            Array.from(row.columns).forEach((column: any, colIndex: any) => {
              if (column.name === this.currentColumnName) {
                let coordsStr = '';
                coordsStr = columnExtratedData.location[0].coords.toString();

                let columnObj: any = {
                  name: column.name,
                  content: columnExtratedData.text,
                  locations: columnExtratedData.location,
                  locations_list: [{ page: this.page, coords: [coordsStr] }],
                  is_validated: false,
                  value: columnExtratedData.value,
                  formatted_value: columnExtratedData.formatted_value,
                  extraction_method: 'AI',
                };

                if (column.is_extra_column) {
                  columnObj.is_extra_column = true;
                }

                this.record.tables[0].rows[rowIndex].columns[colIndex] = [];
                this.record.tables[0].rows[rowIndex].columns[colIndex] =
                  JSON.parse(JSON.stringify(columnObj));
                 return;
            }
          });
        }
      });
      this.$forceUpdate();
    },

    deleteColumnDataForReSelection() {
      Array.from(this.record.tables[0].rows).forEach(
        (row: any, rowIndex: any) => {
          if (row.id === this.currentRowId) {
            Array.from(row.columns).forEach((column: any, colIndex: any) => {
              if (column.name === this.currentColumnName) {
                column.locations = [];
                column.locations_list = [];
                column.formatted_value = '';
                column.value = '';
                column.content = '';
                return;
              }
            });
          }
        },
      );
      const event = new CustomEvent('reload_line_items', {
        detail: {
          apiData: this.record,
          currentRowId: this.currentRowId,
          currentColumnName: this.currentColumnName,
        },
      });
      document.dispatchEvent(event);
    },

    validateSelectedColumn() {
      Array.from(this.record.tables[0].rows).forEach(
        (row: any, rowIndex: any) => {
          if (row.id === this.currentRowId) {
            Array.from(row.columns).forEach((column: any, colIndex: any) => {
              if (column.name === this.currentColumnName) {
                column.is_validated = true;
                return;
              }
            });
          }
        },
      );
    },

    async saveDataForV3(autoTable = false) {
      const actionLockAcquired = await this.hasActionAcquiredLock();
      if (!actionLockAcquired) {
        return;
      }

      let data: any = this.record;
      this.showLoading();

      if (data.hasOwnProperty('table_data_copy')) {
        delete data['table_data_copy'];
      }

      let formData = new FormData();
      formData.append('data', JSON.stringify(data));

      let response: any;
      try {
        formData.append('org_id', getOrgId());
        response = await axios.post(
          api.save_table_train_data + this.record.doc_id,
          formData,
          {
            headers: {
              Authorization: 'Bearer ' + this.token,
            },
          },
        );
        if (response.data.success === false) {
          throw response;
        }
        if (autoTable) {
          this.autoDetectTables();
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    addMappingFlag() {
      let value = '';
      if (
        this.$route.query &&
        (this.$route.query.get_mapping_rules === 'true' ||
          this.$route.query.get_mapping_rules === 'false')
      ) {
        value = this.$route.query.get_mapping_rules;
      }
      return value;
    },

    rulesDeleted() {
      this.ai_rules = 0;
      const event = new CustomEvent('TE_gauge_calculation', {
        detail: { min_table_effective_weight: 0 },
      });
      document.dispatchEvent(event);
    },

    callSplitTextAction(e: any) {
      this.performSplitText(e);
    },

    async performSplitText(e: any) {
      if (!e || !this.record || !this.record.tables) {
        return;
      }
      this.split_text = e.detail === true ? true : false;
      this.prepareTableMap(this.record.tables[0].locations_list);
      this.addExtractedColumns();
      await this.saveTableCoordinates('add_split_text');
    },

    addExtractedColumns() {
      if (
        !this.extracted_columns ||
        Object.keys(this.extracted_columns).length === 0
      ) {
        return;
      }
      for (let [page_no, selectedSeparators] of Object.entries(
        this.extracted_columns,
      )) {
        selectedSeparators = this.sortNumbericArray(selectedSeparators);
        page_no = page_no.substring(5);
        this.addColumnsToTableMap(selectedSeparators, page_no);
      }
    },

    saveDataOnChanges() {
      if (this.table_train === true) {
        this.saveDataForV3();
        return;
      }
      if (!this.isReadOnly) {
        const event = new CustomEvent('save_data', {});
        document.dispatchEvent(event);
      }
    },

    disabledCustomColumnsDialog() {
      const event = new CustomEvent('open_disabled_custom_columns_view', {});
      document.dispatchEvent(event);
    },

    isDebugFlagHandler() {
      this.is_debug = false;
      if (this.$route.query && this.$route.query.is_debug === 'true') {
        this.is_debug = true;
      }
    },

    viewOCRDocument() {
      let route = this.$router.resolve({
        path: '/ocr-document/' + this.docId + '/' + this.page,
      });
      window.open(
        route.href,
        '_blank',
        'location=yes,toolbar=yes,scrollbars=yes,resizable=yes,left=500,width=1500,height=1000',
      );
    },

    changeOrigin() {
      this.saveTableCoordinates('doc_locale');
      this.changeOriginConfirmDialog = false;
    },

    async fetchLanguageOptions() {
      let response: any;
      try {
        let token: string = this.getToken();
        response = await axios.get(
          addOrgIdQueryString(api.get_items_from_dictionary + 'DOC_ORIGIN'),
          {
            headers: {
              Authorization: token,
            },
          },
        );

        if (!response.data || Object.keys(response.data).length === 0) {
          throw response;
        }
        this.language_origin_list = [];
        for (const prop in response.data) {
          let option = response.data[prop] as dynamicObj;
          let description = !option.description ? '' : option.description;
          this.language_origin_list.push(
            Object.assign(
              {},
              {
                value: option.value,
                label: option.label,
                description: description.replaceAll('\\n', '<br />'),
              },
            ),
          );
        }
        setWithExpiry('language_origin_list', this.language_origin_list);
        this.setLanguage();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    setLanguage() {
      this.force_ocr_table_train = false;
      const doc_origin = this.record.doc_origin;
      if (doc_origin) {
        this.languageOrigin = doc_origin;
      }
    },

    isOcrButtonEnabled() {
      let isEnabled = true;

      if (this.record.time_logs) {
        const ocr = this.record.time_logs.ocr;
        const ocrDocumnet = this.record.time_logs.ocr_document;

        if (ocrDocumnet || ocr) {
          isEnabled = false;
        }
      }

      return isEnabled;
    },

    clearViewForUnmount() {
      this.ignore_token_validation = false;
    },
  },
  beforeRouteLeave: function (to: any, from: any, next: any) {
    // Before leaving this page, lets take backup of everything first
    notify.dismissAll();
    this.releaseDocLock({ doc_id: this.record.doc_id });
    this.page = 1;
    this.resetDocStore(to.fullPath);
    next();
  },
  setup() {
    const doc_store = useDocumentStore();
    const {
      record,
      notifications,
      error,
      confirmationForPoConnectionReset,
      get_cached_data_id,
      extractable,
      has_ai_table,
      is_manual_training_allowed,
      doctype,
      bannerBg,
      po_enable,
    } = storeToRefs(doc_store);
    const {
      getDocumentById,
      setRecordFromCache,
      setDataToCache,
      removeCache,
      resetDocStore,
      setManualTraining,
    } = doc_store;

    const doc_lock_store = useDocLockStore();
    const { releaseDocLock, hasActionAcquiredLock, setDocLockStoreDisable } =
      doc_lock_store;
    const { doc_lock } = storeToRefs(doc_lock_store);

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();

    const settings_store = useSettingStore();
    const { getSetting } = settings_store;

    const auth_token_store = useAuthTokenStore();
    // ignore_token_validation must come from the store: assigning to a plain
    // `this.ignore_token_validation` landed on the component instance and the
    // flag never reached getValidatedToken() (DOCB-13929). storeToRefs gives a
    // writable ref, so `this.ignore_token_validation = true` sets store state.
    const { token, ignore_token_validation } = storeToRefs(auth_token_store);
    const { setAuthToken } = auth_token_store;

    const user_store = useUserStore();
    const { getProfile } = user_store;

    let data: any = [];
    return {
      token,
      ignore_token_validation,
      doctype,
      bannerBg,
      po_enable,
      is_manual_training_allowed,
      setManualTraining,
      has_ai_table,
      confirmationForPoConnectionReset,
      doc_fetch_error: ref(error),
      notifications,
      record,
      get_cached_data_id,
      extractable,
      setDocLockStoreDisable,
      hasActionAcquiredLock,
      setRecordFromCache,
      getDocumentById,
      releaseDocLock,
      setDataToCache,
      resetDocStore,
      setAuthToken,
      removeCache,
      getProfile,
      getSetting,
      doc_lock,
      docId: ref(''),
      page: ref(1),
      image: ref(''),
      images: ref(data),
      splitterModel: ref(60),
      tableAreasStr: ref(''),
      isReadOnly: ref(false),
      isRowMode: ref(false),
      baseUrl: DOC2API_URL,
      table_train: ref(false),
      tb_version: 'default',
      training_mode: ref(false),
      ai_rules: ref(0),
      ai_tables: ref(0),
      extracted_columns: ref({} as dynamicObj),
      isExtractedColumnMode: ref(false),
      openCodeEditor: ref(false),
      split_text: ref(false),
      is_debug: ref(false),
      changeOriginConfirmDialog: ref(false),
      language_origin_list: data,
      languageOrigin: ref(''),
      force_ocr_table_train: ref(false),
      trigger_document_lock: ref(false),
      document_version: ref(0),
      api_tries: ref(0),
      error_message: ref(''),
      ai_table_warning: ref(false),
      tokenQueryParam,
      getTokenQueryParam: refreshTokenParam,
    };
  },
});
</script>

