<template>
  <div class="image-decorator" ref="image-area" id="image_area">
    <div id="screenshot_container">
      <img
        @load="prepareImageData"
        id="screenshot"
        class="original-image"
        :src="url"
        alt="Original Image"
        v-if="url"
        :width="width"
      />
      <div
        class="select-areas--overlay"
        :style="{
          opacity: opacityOverlay,
          position: 'absolute',
          width: originImgSize.w + 'px',
          height: originImgSize.h + 'px',
          display: 'block',
        }"
      ></div>

      <div
        v-if="isRowMode === false"
        class="pointer-events-none"
        id="draw"
        :style="{
          'background-color': 'rgb(0, 0, 0)',
          opacity: 0,
          position: 'absolute',
          width: originImgSize.w + 'px',
          height: originImgSize.h + 'px',
        }"
        @mousedown="mouseDown"
        @mousemove="mouseMove"
      ></div>

      <div
        v-else
        class="pointer-events-none"
        id="draw"
        :style="{
          'background-color': 'rgb(0, 0, 0)',
          opacity: 0,
          position: 'absolute',
          width: originImgSize.w + 'px',
          height: originImgSize.h + 'px',
        }"
      ></div>

      <div v-for="item in areas" :key="item.id">
        <div
          v-if="isRowMode === false"
          @mousedown.stop.prevent="startMove(item, $event)"
          @mousemove="doMove(item, $event)"
          :id="'draw_' + item.areaTag"
        >
          <div
            class="select-areas--outline"
            :style="{
              opacity: item.areaType === 'column' ? '1' : opacityOutline,
              position: 'absolute',
              cursor: 'default',
              width: item.width + 4 + 'px',
              height: item.height + 4 + 'px',
              left: areaDisplayPosX(item) - 2 + 'px',
              top: areaDisplayPosY(item) - 2 + 'px',
              'z-index': item.areaType === 'column' ? '2' : item.z,
            }"
          ></div>
          <div
            class="select-areas--background_area"
            :style="{
              background:
                item.background +
                `#fff url('${url}') -${item.x}px -${item.y}px / ${originImgSize.w}px ${originImgSize.h}px no-repeat`,
              position: 'absolute',
              cursor: enableEditing === true ? 'move' : 'pointer',
              width: item.width + 'px',
              height: item.height + 'px',
              left: areaDisplayPosX(item) + 'px',
              top: areaDisplayPosY(item) + 'px',
              'z-index': item.z + 2,
            }"
            @click="changeResizable(item.id)"
          ></div>
          <div
            v-if="item.resizable && enableEditing === true"
            class="delete-area"
            :style="{
              display: 'block',
              left: areaDisplayPosX(item) + item.width + 'px',
              top: areaDisplayPosY(item) - 25 + 'px',
              'z-index': item.z + 2,
            }"
            @click="deleteSelected(item.id)"
          >
            <div class="select-areas--delete_area"></div>
          </div>
          <!-- resize handler -->
          <Resizable
            v-if="enableEditing === true"
            :item="item"
            :posImg="posImg"
            :pos-correction="posCorrection"
            @startDrag="startDrag"
            @doDrag="doDrag"
          />
        </div>

        <div v-else :id="'draw_' + item.areaTag">
          <div
            class="select-areas--outline"
            :class="
              item.areaType == 'column' ? 'column_outline' : 'row_outline'
            "
            :area-tag="item.areaTag + '_border'"
            :area-type="item.areaType + '_border'"
            :style="{
              opacity: 0.2,
              position: 'absolute',
              cursor: 'default',
              width: item.width + (item.areaType == 'column' ? 2 : 4) + 'px',
              height: item.height + 4 + 'px',
              left: areaDisplayPosX(item) - 2 + 'px',
              top: areaDisplayPosY(item) - 2 + 'px',
              'z-index': 'unset',
            }"
          ></div>
          <div
            class="select-areas--background_area"
            :class="
              item.areaType == 'column'
                ? 'column_background_area'
                : 'row_background_area'
            "
            :area-tag="item.areaTag + '_area'"
            :area-type="item.areaType + '_area'"
            @click="decideAction(item)"
            :style="{
              background:
                item.background +
                `#fff url('${url}') -${item.x}px -${item.y}px / ${originImgSize.w}px ${originImgSize.h}px no-repeat`,
              position: 'absolute',
              cursor: 'pointer',
              width: item.width - (item.areaType == 'column' ? 3 : 0) + 'px',
              height: item.height + 'px',
              left: areaDisplayPosX(item) + 'px',
              top: areaDisplayPosY(item) + 'px',
              'z-index': 'unset',
              opacity: item.opacity,
            }"
          ></div>
        </div>
      </div>
    </div>
    <div class="c-crop--hide_main">
      <img id="c-crop--hide_img" :src="url" alt="" :width="width" />
    </div>

    <!-- OVERLAY DIALOG START -->

    <q-dialog
      v-model="correctionDialog"
      persistent
      transition-show="scale"
      transition-hide="scale"
    >
      <q-card class="bg-teal text-white" style="width: 300px">
        <q-card-section>
          <div class="text-h6">{{ $t('confirmation') }}</div>
        </q-card-section>

        <q-card-section class="q-pt-none">
          {{ $t('is_draw_correct') }}
        </q-card-section>

        <q-card-actions align="right" class="bg-white text-teal">
          <q-btn
            flat
            :label="$t('cancel')"
            v-close-popup
            @click="cancelAreaSelection()"
          />
          <q-btn
            flat
            data-cy="no"
            :label="$t('no')"
            v-close-popup
            @click="reSelectArea()"
          />
          <q-btn
            flat
            data-cy="yes"
            :label="$t('yes')"
            v-close-popup
            @click="saveSelectionResult()"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
    <!-- OVERLAY DIALOG END -->
  </div>
</template>
<script lang="ts">
import Resizable from './Resizable.vue';
import { SessionStorage } from 'quasar';
import { defineComponent, ref } from 'vue';
import documentUtil from 'src/utils/documentUtil';
import ColorGenerator from 'src/utils/ColorGenerator';
import { $, TableCoordinateType } from '../pages/assets';
import { rowRgbaColor, rowRgbaColorStr } from 'src/constants';

let _this: any;
let tableData: TableCoordinateType = {
  columns: [],
  table_areas: [],
};

let imageArea: HTMLElement;
let screenshot: HTMLElement;

export default defineComponent({
  mixins: [ColorGenerator, documentUtil],
  data() {
    return {
      mousedown: ref(false), // state mouse down event
      originImgSize: {
        // root size image
        w: 0,
        h: 0,
        r: 0,
      },
      url: this.cropUrl,
      posImg: {
        // position box image in screen
        top: 0,
        left: 0,
      },
      areas: [
        {
          id: 1,
          x: 10,
          y: 10,
          startX: 10,
          startY: 10,
          width: 10,
          height: 10,
          z: 0,
          resizable: false,
          opacity: '1',
          background: rowRgbaColorStr,
          areaTag: 'table',
          areaType: 'table',
          rowId: '',
        },
      ],
      currentSelectedItem: ref(),
      latestAreaItem: { startX: 0, startY: 0, endX: 0, endY: 0 },
      scrollLeft: 0,
      scrollTop: 0,
      moveTempX: 0,
      moveTempY: 0,
      moveCurrentX: 0,
      moveCurrentY: 0,
      temp: 0,
      dragdown: false, // state mouse event drag,
      move: false,
      imageHeight: 0,
      imageWidth: 0,
      correctionDialog: false,
      numberOfAreas: 0,
      oldArea: '',
      disableImageRowsClick: false,
      delay: 170,
      clicks: 0,
      timer: ref(),
      delay2: ref(170),
      timer2: ref(),
    };
  },
  props: {
    cropUrl: {
      type: String,
      // default: 'https://scontent.fhan2-3.fna.fbcdn.net/v/t1.0-9/45585072_925043081015026_6599956628924006400_o.jpg?_nc_cat=108&_nc_oc=AQlJUcFj4S_wGeX016thVhmgINU5wDV4xPBNSCIcYSti9Sm5WEPBDYO_kxK4aRP0Emo&_nc_ht=scontent.fhan2-3.fna&oh=052bb05956a1460d014205754da5a15b&oe=5DCC1053'
      default:
        'https://dev.doc2api.cloudintegration.eu/resource/image/1b90b6d5-63b5-446b-92a4-a60d57dc0edd/1.png',
    },
    width: {
      type: Number,
      default: 1500,
    },
    opacityOutline: {
      type: Number,
      default: 0.2,
    },
    opacityOverlay: {
      type: Number,
      default: 0.2,
    },
    posCorrection: {
      type: Boolean,
      default: true,
    },
    tableAreas: {
      type: String,
      default: '',
    },
    isRowMode: {
      type: Boolean,
      default: false,
    },
    enableEditing: {
      type: Boolean,
      default: false,
    },
    // areaOpacity: {
    //   type: String,
    //   default: '1'
    // }
  },
  components: {
    Resizable,
  },
  emits: ['saveColumnCoords', 'toggleExtractedColumnMode'],
  // created () {
  // },
  watch: {
    cropUrl(val) {
      this.url = val;
      setTimeout(() => {
        this.setSize();
      }, 200);
    },
    // send data to parent when list areas change
    // areas () {
    //   setTimeout(() => {
    //     this.getListAreas()
    //   }, 200)
    // },
    tableAreas(val) {
      this.prepareDataForAreas();
    },
    async width(val) {
      await this.setSize();
      this.prepareImageData();
    },
  },
  methods: {
    areaDisplayPosX(area: any): any {
      return area.x + (this.posCorrection ? this.posImg.left : 0);
    },
    areaDisplayPosY(area: any): any {
      return area.y + (this.posCorrection ? this.posImg.top : 0);
    },
    mousePosX(e: any) {
      return e.pageX - this.posImg.left;
    },
    mousePosY(e: any) {
      return e.pageY - this.posImg.top;
    },
    async setSize() {
      if (!this.url) {
        return;
      }
      let imgSize: any = await this.getSize(this.url);
      this.originImgSize = imgSize;
    },
    // Get the size of the src image
    getSize(src: any) {
      let img = this.$el.querySelector('#c-crop--hide_img');
      return new Promise((resolve) => {
        if (src && img) {
          img.onload = function () {
            // Compatible with unacceptable size
            const size = _this.getSizeImg(img);
            resolve(size);
          };
          img.src = src;
        } else {
          resolve({
            w: 0,
            h: 0,
            r: 0,
          });
        }
      });
    },
    getSizeImg(img: any) {
      let w = img.width;
      let h = img.height;
      let r = w === 0 && h === 0 ? 0 : w / h;
      return {
        w: w,
        h: h,
        r: r,
      };
    },
    calcPosOfBox() {
      // set posImg static
      let imageAreaRef: any = this.$refs['image-area'];

      this.scrollLeft =
        window.pageXOffset || document.documentElement.scrollLeft;
      this.scrollTop = window.pageYOffset || document.documentElement.scrollTop;

      let imageAreaTop = imageAreaRef.getBoundingClientRect().top;
      let imageAreaLeft = imageAreaRef.getBoundingClientRect().left;

      this.posImg.top = imageAreaTop + this.scrollTop;

      this.posImg.left = imageAreaLeft + this.scrollLeft;
    },
    manageEventsForColumns(e: any) {
      // if(this.disableImageRowsClick === true) {
      this.clicks++;
      if (this.clicks === 1) {
        this.timer = setTimeout(() => {
          this.clicks = 0;
          this.mouseDown(e);

          let selectedRow: HTMLElement = $(
            '#' + 'draw_' + this.oldArea,
          )!.querySelector('.select-areas--background_area')!;
          selectedRow.style.cursor = 'crosshair';
          selectedRow.addEventListener('mousemove', this.mouseMove);
          return;
        }, this.delay);
      } else {
        this.clicks = 0;
        clearTimeout(this.timer);
        this.dblClickToSelect(e);
      }
      // }
    },
    // draw rectangle on image mouseDown mouseMove mouseUp
    mouseDown(e: any) {
      this.mousedown = true;
      let newAreaId = null;

      if (this.areas.length > 0) {
        // last area id + 1
        newAreaId = this.areas.slice(-1).pop()!.id + 1;
      } else {
        newAreaId = 1;
      }

      this.numberOfAreas = newAreaId;

      if (
        this.latestAreaItem.startX != 0 &&
        this.latestAreaItem.startY != 0 &&
        this.isRowMode === false
      ) {
        let startX = this.latestAreaItem.startX;
        let startY = this.latestAreaItem.startY;

        let endX = e.layerX;
        let endY = e.layerY;

        let width = endX - startX;
        let height = endY - startY;
        if (width < 0 || height < 0) {
          endX = startX;
          endY = startY;

          startX = e.layerX;
          startY = e.layerY;

          width = endX - startX;
          height = endY - startY;
        }

        let newArea = {
          id: newAreaId,
          x: startX,
          y: startY,
          startX: startX,
          startY: startY,
          width: width,
          height: height,
          z: 0,
          resizable: false,
          opacity: '1',
          background: this.isRowMode ? rowRgbaColorStr : '',
          areaTag: this.isRowMode ? 'column' : 'table',
          areaType: this.isRowMode ? 'column' : 'table',
          rowId: '',
        };
        this.temp = newArea.id;
        this.areas.push(newArea);
        this.latestAreaItem = { startX: 0, startY: 0, endX: 0, endY: 0 };
        return;
      }

      if (newAreaId) {
        let newArea = {
          id: newAreaId,
          x: this.mousePosX(e),
          y: this.mousePosY(e),
          startX: this.mousePosX(e),
          startY: this.mousePosY(e),
          width: 0,
          height: 0,
          z: 0,
          resizable: false,
          opacity: '1',
          background: this.isRowMode ? rowRgbaColorStr : '',
          areaTag: this.isRowMode ? 'column' : 'table',
          areaType: this.isRowMode ? 'column' : 'table',
          rowId: '',
        };
        this.areas.push(newArea);
        this.temp = newArea.id;
        this.latestAreaItem.startX = this.mousePosX(e);
        this.latestAreaItem.startY = this.mousePosY(e);
        this.latestAreaItem.endX = 0;
        this.latestAreaItem.endY = 0;
      }
    },

    mouseMove(e: any) {
      // logInfo('mouseMove');
      if (this.mousedown) {
        this.areas
          .filter((x: any) => x.id === this.temp)
          .map((item: any) => {
            let x = e.pageX - this.posImg.left;
            let y = e.pageY - this.posImg.top;
            let width = item.startX - x;
            let height = item.startY - y;
            if (width < 0) {
              width *= -1;
              x -= width;
            }
            if (height < 0) {
              height *= -1;
              y -= height;
            }

            item.x = x;
            item.y = y;
            item.width = width;
            item.height = height;
          });
        this.latestAreaItem = { startX: 0, startY: 0, endX: 0, endY: 0 };
      }
    },

    mouseUp() {
      if (this.isRowMode === true && this.disableImageRowsClick === false) {
        return;
      }

      this.timer2 = setTimeout(() => {
        this.mousedown = false;
        // delete all point width is less then 3
        this.areas = this.areas.filter(
          (item: any) => item.width >= 3 && item.height >= 3,
        );
        this.endMove();
        this.endDrag();
        // this.setTableAreas();
        this.prepareTableArea();

        // check if mode is row and new area on image is created
        if (
          this.isRowMode === true &&
          this.findAreaById(this.numberOfAreas) === true
        ) {
          this.correctionDialog = true;
        }
      }, this.delay2);
    },

    // after click rectangle area select active resizable and dragable
    changeResizable(id: any) {
      this.areas
        .filter((item: any) => item.id === id)
        .map((item: any) => {
          item.resizable = true;
          item.z = 100;
        });
      this.areas
        .filter((item: any) => item.id !== id)
        .map((item: any) => {
          item.resizable = false;
          item.z = 0;
        });
    },
    // delete item area
    deleteSelected(id: any) {
      this.areas = this.areas.filter((item: any) => item.id !== id);
      this.prepareTableArea();
    },
    // find item area
    findAreaById(id: any) {
      let found = false;
      for (let area of this.areas) {
        if (area.id === id) {
          found = true;
          break;
        }
      }
      return found;
    },
    // delete item area
    deleteSelectedColumn(item: any) {
      const event = new CustomEvent('delete_select_area_column', {});
      document.dispatchEvent(event);
      // this.areas = this.areas.filter(item => item.id !== id);
      // this.prepareTableArea();
    },
    // validate column value
    validateColumn(item: any) {
      const event = new CustomEvent('validate_selected_column', {});
      document.dispatchEvent(event);
    },

    // drag point around rectangle on image startDrag doDrag endDrag
    startDrag() {
      this.dragdown = true;
    },

    doDrag(item: any, type: any, e: any) {
      if (this.dragdown) {
        switch (type) {
          case 'w':
            // fix drag outside box w position
            if (e.pageX - this.posImg.left >= 0) {
              item.width = item.width + item.x - e.pageX + this.posImg.left;
              item.x = e.pageX - this.posImg.left;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            break;
          case 'sw':
            // fix drag outside box sw position
            if (e.pageX - this.posImg.left >= 0) {
              item.width = item.width + item.x - e.pageX + this.posImg.left;
              item.x = e.pageX - this.posImg.left;
            }
            if (e.pageY - this.posImg.top <= this.originImgSize.h) {
              item.height = e.pageY - this.posImg.top - item.y;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 's':
            // fix drag outside box s position
            if (e.pageY - this.posImg.top <= this.originImgSize.h) {
              item.height = e.pageY - this.posImg.top - item.y;
            }
            // fix minimum area
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 'se':
            // fix drag outside box se position
            if (e.pageX - this.posImg.left <= this.originImgSize.w) {
              item.width = e.pageX - this.posImg.left - item.x;
            }
            if (e.pageY - this.posImg.top <= this.originImgSize.h) {
              item.height = e.pageY - this.posImg.top - item.y;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 'e':
            // fix drag outside box e position
            if (e.pageX - this.posImg.left <= this.originImgSize.w) {
              item.width = e.pageX - this.posImg.left - item.x;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            break;
          case 'ne':
            // fix drag outside box ne position
            if (e.pageX - this.posImg.left <= this.originImgSize.w) {
              item.width = e.pageX - this.posImg.left - item.x;
            }
            if (e.pageY - this.posImg.top >= 0) {
              item.height = item.height + (item.y + this.posImg.top - e.pageY);
              item.y = e.pageY - this.posImg.top;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 'n':
            // fix drag outside box n position
            if (e.pageY - this.posImg.top >= 0) {
              item.height = item.height + (item.y + this.posImg.top - e.pageY);
              item.y = e.pageY - this.posImg.top;
            }
            // fix minimum area
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 'nw':
            // fix drag outside box nw position
            if (e.pageY - this.posImg.top >= 0) {
              item.height = item.height + (item.y + this.posImg.top - e.pageY);
              item.y = e.pageY - this.posImg.top;
            }
            if (e.pageX - this.posImg.left >= 0) {
              item.width = item.width + item.x - e.pageX + this.posImg.left;
              item.x = e.pageX - this.posImg.left;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          default:
            break;
        }
      }
    },

    endDrag() {
      this.dragdown = false;
    },

    // move rectangle area startMove doMove endMove
    startMove(item: any, e: any) {
      if (this.enableEditing === true) {
        this.move = true;
        this.moveTempX = e.clientX;
        this.moveTempY = e.clientY;
        this.moveCurrentX = item.x;
        this.moveCurrentY = item.y;
      } else {
        this.move = true;
      }
    },

    doMove(item: any, e: any) {
      if (this.enableEditing === false) {
        return;
      }
      if (this.move) {
        let x = this.moveCurrentX + (e.clientX - this.moveTempX);
        let y = this.moveCurrentY + (e.clientY - this.moveTempY);
        let maxX = this.originImgSize.w - item.width;
        let maxY = this.originImgSize.h - item.height;
        if (x > 0 && y > 0 && x < maxX && y < maxY) {
          item.x = x;
          item.y = y;
        }
      }
    },

    endMove() {
      this.move = false;
    },

    // send data from child to parent $emit
    // getListAreas () {
    //   this.$emit('getListAreas', this.areas);
    // },
    // this function only creats a test overlay reactangle. just to understand what data is expexted to creat corret overlay
    creatReactangle(
      x: number,
      y: number,
      width: number,
      height: number,
      areaTag: string,
      opacity: string,
      background: string,
      rowId: string,
      areaType: string,
    ) {
      let newAreaId = null;
      if (this.areas.length > 0) {
        // last area id + 1
        newAreaId = this.areas.slice(-1).pop()!.id + 1;
      } else {
        newAreaId = 1;
      }
      if (newAreaId) {
        let newArea = {
          id: newAreaId,
          x: x,
          y: y,
          startX: x,
          startY: y,
          width: width,
          height: height,
          z: 0,
          resizable: false,
          opacity: opacity,
          background: background,
          areaTag: areaTag,
          areaType: areaType,
          rowId: rowId,
        };
        this.areas.push(newArea);
        this.temp = newArea.id;
      }
    },
    prepareImageData() {
      screenshot = $('#screenshot') as HTMLElement;
      if (screenshot) {
        this.imageWidth = screenshot.offsetWidth;
        this.imageHeight = screenshot.offsetHeight;
        this.prepareDataForAreas();
        // this.$emit('toggleExtractedColumnMode', false);
      }
    },
    prepareDataForAreas() {
      this.removeExistingConfirmationOverlays();

      this.areas = [];

      if (this.isRowMode) {
        this.delay2 = 170;
        this.disableImageRowsClick = false;
        this.disableSelectionForRow(this.oldArea);
        this.prepareRowAreas();
      } else {
        this.delay2 = 1;
        this.prepareTableAreas();
      }
    },
    prepareCustomizedAreas() {
      this.areas = [];
      this.prepareTableAreas();
      this.prepareRowAreas();
    },
    prepareRowAreas() {
      if (
        SessionStorage.has('table_rows_data') &&
        SessionStorage.getItem('table_rows_data') != null &&
        SessionStorage.getItem('table_rows_data') != ''
      ) {
        let tableDataStr = SessionStorage.getItem('table_rows_data');
        tableData = JSON.parse(tableDataStr as string);
      } else {
        tableData = { columns: [], table_areas: [] };
      }
      let tableRect = [];
      if (tableData && tableData.table_areas.length > 0) {
        Array.from(tableData.table_areas).forEach((table_area: any) => {
          tableRect = table_area.coord.split(',');

          let startX = Math.round(this.imageWidth * tableRect[0]);
          let startY = Math.round(this.imageHeight * tableRect[1]);
          let endX = Math.round(this.imageWidth * tableRect[2]);
          let endY = Math.round(this.imageHeight * tableRect[3]);

          let width = endX - startX;
          let height = endY - startY;

          let areaTag: string = table_area.id;
          let opacity: string = table_area.opacity;
          let background: string = table_area.background;
          let areaType: string = table_area.type;
          let rowId: string = table_area.row_id;

          this.creatReactangle(
            startX,
            startY,
            width,
            height,
            areaTag,
            opacity,
            background,
            rowId,
            areaType,
          );
        });
      }
    },

    prepareTableAreas() {
      if (
        SessionStorage.has('table_data') &&
        SessionStorage.getItem('table_data') != null &&
        SessionStorage.getItem('table_data') != ''
      ) {
        let tableDataStr = SessionStorage.getItem('table_data');
        tableData = JSON.parse(tableDataStr as string);
      } else {
        tableData = { columns: [], table_areas: [] };
      }

      let tableRect = [];
      if (tableData && tableData.table_areas.length > 0) {
        Array.from(tableData.table_areas).forEach((table_area: any) => {
          tableRect = table_area.split(',');

          let startX = this.getCoordinate(tableRect[0]);
          let startY = this.getCoordinate(tableRect[1]);
          let endX = this.getCoordinate(tableRect[2]);
          let endY = this.getCoordinate(tableRect[3]);

          startX = Math.round(this.imageWidth * startX);
          startY = Math.round(this.imageHeight * startY);
          endX = Math.round(this.imageWidth * endX);
          endY = Math.round(this.imageHeight * endY);

          let width = endX - startX;
          let height = endY - startY;

          if (width < 0) {
            width *= -1;
            startX -= width;
          }
          if (height < 0) {
            height *= -1;
            startY -= height;
          }

          let tagArea = 'table_' + Math.floor(Math.random() * 100000);

          this.creatReactangle(
            startX,
            startY,
            width,
            height,
            tagArea,
            '1',
            '',
            '',
            'table',
          );
        });
      }
    },
    getCoordinate(coordinate: number) {
      if (coordinate < 0) {
        return 0;
      } else if (coordinate > 1) {
        return 1;
      }

      return coordinate;
    },
    getTableAreaAsString(
      startX: number,
      startY: number,
      endX: number,
      endY: number,
    ): string {
      let x1 = startX / this.imageWidth;
      let y1 = startY / this.imageHeight;
      let x2 = endX / this.imageWidth;
      let y2 = endY / this.imageHeight;

      return (
        x1.toString() +
        ',' +
        y1.toString() +
        ',' +
        x2.toString() +
        ',' +
        y2.toString()
      );
    },
    prepareTableArea() {
      tableData.table_areas = [];
      Array.from(this.areas).forEach((data: any) => {
        let endX = data.width + data.x;
        let endY = data.height + data.y;

        tableData.table_areas.push(
          this.getTableAreaAsString(data.x, data.y, endX, endY),
        );
      });
      if (this.isRowMode === false) {
        SessionStorage.set('table_data', JSON.stringify(tableData));
      }
    },
    calculateLeftPosition(item: any): string {
      let left = this.areaDisplayPosX(item) + item.width;
      if (left + 50 >= this.imageWidth) {
        left = this.areaDisplayPosX(item) - 60;
      }
      return left + 'px';
    },
    calculatePositionFromTop(item: any): string {
      let top = this.areaDisplayPosY(item) - 25;
      if (top < 0) {
        top = this.areaDisplayPosY(item);
      }
      return top + 'px';
    },
    /**
     * Cancel overlay div. Nothing to do.
     */
    cancelAreaSelection() {
      this.deleteSelected(this.numberOfAreas);
      this.correctionDialog = false;
      this.numberOfAreas = 0;
      this.disableSelectionForRow(this.oldArea);
    },
    reSelectArea() {
      this.deleteSelected(this.numberOfAreas);
      this.correctionDialog = false;
      this.numberOfAreas = 0;
      setTimeout(() => {
        let selectedRow: HTMLElement = $(
          '#' + 'draw_' + this.oldArea,
        )!.querySelector('.select-areas--background_area')!;
        selectedRow.style.cursor = 'crosshair';
      }, 10);
    },
    saveSelectionResult() {
      if (tableData.table_areas.length > 0) {
        this.correctionDialog = false;
        this.disableImageRowsClick = false;
        // this.prepareDataForAreas();

        let tableArea = tableData.table_areas[tableData.table_areas.length - 1];
        let coord: any;
        if (tableArea.hasOwnProperty('coord')) {
          coord = tableArea.coord;
        } else {
          coord = tableArea;
        }

        this.disableSelectionForRow(this.oldArea);

        this.numberOfAreas = 0;

        this.$emit('saveColumnCoords', coord);
      }
    },
    decideAction(item: any) {
      let areaTag: string = item.areaTag;
      let areaType: string = item.areaType;
      let rowId: string = item.rowId;

      this.currentSelectedItem = item;
      this.removeExistingConfirmationOverlays();

      if (this.disableImageRowsClick === true) {
        return;
      }

      this.disableSelectionForRow(this.oldArea);

      if (areaType === 'column') {
        this.numberOfAreas = 0;

        // clear old selection

        let image_container_el: HTMLElement | null = $('#screenshot_container');

        let columnAreas = image_container_el!.querySelectorAll(
          'div.column_background_area',
        );
        Array.from(columnAreas).forEach((element: any) => {
          let selectionBackground = element.style.background.split('100%)');
          element.style.background = rowRgbaColor + selectionBackground[1];
        });

        let imageArea =
          image_container_el!.querySelectorAll('div.column_outline');
        Array.from(imageArea).forEach((element: any) => {
          element.style.opacity = '0.2';
          if ((element as HTMLElement).nextSibling) {
            ((element as HTMLElement).nextSibling as HTMLElement).style.border =
              'unset';
          }
        });

        this.oldArea = rowId;
        let selectedInput = $(
          '#' + 'input_' + areaTag + '_' + rowId,
        ) as HTMLElement;

        if (selectedInput) {
          let selectedArea: HTMLElement | null = $('#' + 'draw_' + areaTag);

          let selectedAreaBorderElm: HTMLElement = selectedArea!.querySelector(
            '.select-areas--outline',
          )!;
          selectedAreaBorderElm.style.opacity = '0';

          let elems = document
            .querySelector('#line_item_table')!
            .querySelectorAll('label.active-border-2px');
          Array.from(elems).forEach((element: any) => {
            element.classList.remove('active-border-2px');
          });

          let selection = selectedArea!.querySelector(
            '.select-areas--background_area',
          ) as HTMLElement;
          selection.style.border = '2px';
          selection.style.borderStyle = 'solid';
          selection.style.borderColor = '#8800ff';

          selectedInput.scrollIntoView();
          selectedInput
            .querySelector('label')!
            .classList.add('active-border-2px');

          let extraction_method_els = selectedInput.querySelector(
            'label.extraction_method',
          );

          if (extraction_method_els != null) {
            let column_value = selectedInput.dataset.columnValue;
            let score_description = selectedInput.dataset.scoreDescription;
            let detailObj = {
              value: column_value,
              score: score_description,
              selection: selection,
            };

            this.prepareOverlay({ detail: detailObj });
          }
        } else {
          logError('not mapped');
        }
      } else {
        this.numberOfAreas = 0;

        // high light selected row
        let selectedRow = document.getElementById(areaTag) as HTMLElement;
        selectedRow.classList.add('active-table-row');

        // remove old high light selected row
        if (this.oldArea != '') {
          let oldSelectedRow = document.getElementById(
            this.oldArea,
          ) as HTMLElement;
          oldSelectedRow.classList.remove('active-table-row');
        }

        let detailObj = { rowId: areaTag, columnName: null };
        const event = new CustomEvent('get_table_rows_areas', {
          detail: detailObj,
        });
        document.dispatchEvent(event);

        this.oldArea = areaTag;
      }
    },
    enableSelectionForRow(e: any) {
      this.disableImageRowsClick = true;
      this.disableSelectionForRow(this.oldArea);

      let areaTag = e.detail;
      this.oldArea = e.detail;
      let selectedRow: HTMLElement = $('#' + 'draw_' + areaTag)!.querySelector(
        '.select-areas--background_area',
      )!;

      selectedRow.style.cursor = 'crosshair';
      selectedRow.addEventListener('mousedown', this.manageEventsForColumns);
    },
    disableSelectionForRow(oldArea: string) {
      if (oldArea != '') {
        if ($('#' + 'draw_' + oldArea)) {
          let oldElement: HTMLElement = $(
            '#' + 'draw_' + oldArea,
          )!.querySelector('.select-areas--background_area')!;

          oldElement.style.cursor = 'pointer';
          oldElement.removeEventListener(
            'mousedown',
            this.manageEventsForColumns,
          );
          oldElement.removeEventListener('mousemove', this.mouseMove);
        }
      }
    },
    dblClickToSelect(ev: any) {
      this.disableSelectionForRow(this.oldArea);
      let coord = this.getTableAreaAsString(
        this.mousePosX(ev),
        this.mousePosY(ev),
        this.mousePosX(ev),
        this.mousePosY(ev),
      );
      this.$emit('saveColumnCoords', coord);
    },
    prepareOverlay(e: any) {
      let column_value: string = e.detail.value;
      let score_description: string = e.detail.score;
      let selection: HTMLElement = e.detail.selection;

      let scoreObj = null;
      if (score_description != null && score_description !== '') {
        scoreObj = {
          score: score_description,
          background: this.getColor(Number(score_description)),
        };
      }
      this.drawOverlay(String(column_value), selection, scoreObj);
    },
    drawOverlay(heading: string, rectElement: any, scoreObj: any) {
      // this.connectionId = connectionId;
      this.removeExistingConfirmationOverlays();

      const dimensionDetails = this.getOffset(rectElement);

      const divOverlay = document.createElement('div');
      divOverlay.setAttribute('id', 'confirmation_overlay');
      divOverlay.style.position = 'absolute';
      divOverlay.style.zIndex = '99999';
      divOverlay.style.left = dimensionDetails.left + 'px';
      divOverlay.style.top =
        (+dimensionDetails.top + +dimensionDetails.height + 6).toString() +
        'px';
      divOverlay.style.background = '#ffffff';
      divOverlay.style.color = '#898989';
      divOverlay.style.minHeight = '65px';
      divOverlay.style.minWidth = '100px';
      divOverlay.style.maxWidth = this.imageWidth * 0.75 + 'px';
      divOverlay.style.textAlign = 'center';
      divOverlay.style.padding = '5px 10px 5px 10px';
      divOverlay.style.letterSpacing = '1px';
      divOverlay.style.borderRadius = '7px';
      divOverlay.style.boxShadow = `0 1px 2px rgba(0,0,0,0.07),
      0 2px 4px rgba(0,0,0,0.07),
      0 4px 8px rgba(0,0,0,0.07),
      0 8px 16px rgba(0,0,0,0.07),
      0 16px 32px rgba(0,0,0,0.07),
      0 32px 64px rgba(0,0,0,0.07);`;

      divOverlay.innerHTML = `<div>
                    <div><b>${heading}</b></div>
                    <div>
                    <span id='divOverlayWrong'>
                      <span style='display: inline-flex;align-items:center;justify-content:center;border-radius: 50px;box-shadow: 0px 0px 2px #888;padding: 0.5em 0.6em;cursor:pointer;width:20px;height:20px;'>&#x2715;</span>
                    </span>
                    <span id='divOverlayCorrect'>
                      <span style='display: inline-flex;align-items:center;justify-content:center;border-radius: 50px;box-shadow: 0px 0px 2px #888;padding: 0.5em 0.5em;cursor:pointer;width:20px;height:20px;'>&#x2713;</span>
                    </span></div>
                  </div>`;
      document.body.appendChild(divOverlay);
      $('#divOverlayCorrect')?.addEventListener('click', (e: any) => {
        this.removeExistingConfirmationOverlays();
        this.validateColumn(this.currentSelectedItem);
      });
      $('#divOverlayWrong')?.addEventListener('click', (e: any) => {
        this.removeExistingConfirmationOverlays();
        this.deleteSelectedColumn(this.currentSelectedItem);
      });

      // Aligning the div overlay in center
      try {
        const overlay: HTMLElement | null = $('#confirmation_overlay');
        const overlayWidth = $('#confirmation_overlay')?.clientWidth;
        const rectWidth = dimensionDetails.width;
        const gapToDecreaseFromLeft = (+overlayWidth! - +rectWidth) / 2;
        overlay!.style.left =
          +dimensionDetails.left - +gapToDecreaseFromLeft + 'px';

        let totalExpectedHeight =
          +rectElement.getAttribute('width') +
          +rectElement.getAttribute('y') +
          overlay!.offsetHeight;
        if (totalExpectedHeight >= screenshot.offsetHeight) {
          divOverlay.style.top =
            (+dimensionDetails.top - 6 - +overlay!.offsetHeight).toString() +
            'px';
        }

        if (scoreObj) {
          setTimeout(() => {
            this.overlayForScore(overlay, scoreObj);
          }, 10);
        }
      } catch (err) {}
    },
    overlayForScore(rectElement: any, scoreObj: any) {
      let score: string = scoreObj.score;
      let background: string = scoreObj.background;

      const dimensionDetails = this.getOffset(rectElement);

      const divOverlay = document.createElement('div');
      divOverlay.setAttribute('id', 'score_overlay');
      divOverlay.style.position = 'absolute';
      divOverlay.style.zIndex = '99999';
      divOverlay.style.left =
        (+dimensionDetails.left + dimensionDetails.width + 6).toString() + 'px';
      divOverlay.style.top = (+dimensionDetails.top - 15).toString() + 'px';
      divOverlay.style.background = background;
      divOverlay.style.color = '#898989';
      divOverlay.style.fontSize = '14px';
      divOverlay.style.fontWeight = 'bold';
      divOverlay.style.letterSpacing = '2px';
      divOverlay.style.cursor = 'pointer';
      divOverlay.style.padding = '0.1em 0.6em';
      divOverlay.style.border = '1px solid #f5f5f5';
      divOverlay.style.borderRadius = '50px';

      divOverlay.innerHTML = `<div> <span  class='column-score-test' > ${score} </span> </div>`;
      document.body.appendChild(divOverlay);
    },
    getOffset(el: HTMLElement) {
      const rect = el.getBoundingClientRect();
      return {
        left: rect.left + window.pageXOffset,
        right: rect.right + window.pageXOffset,
        top: rect.top + window.pageYOffset,
        width: rect.width || el.offsetWidth,
        height: rect.height || el.offsetHeight,
      };
    },

    handleScroll() {
      this.removeExistingConfirmationOverlays();
    },
  },
  mounted() {
    _this = this;

    this.setSize();
    imageArea = $('#image_area') as HTMLElement;

    imageArea.addEventListener('mousemove', this.calcPosOfBox);
    imageArea.addEventListener('scroll', this.calcPosOfBox);
    this.calcPosOfBox();
    imageArea.addEventListener('mouseup', this.mouseUp);
    document.addEventListener('prepare_overlay', this.prepareOverlay);
    document.addEventListener('reset_table_areas', this.prepareDataForAreas);
    document.addEventListener(
      'enable_column_selection',
      this.enableSelectionForRow,
    );
    document.addEventListener(
      'prepare_customized_areas',
      this.prepareCustomizedAreas,
    );
    $('#image_container')!.parentElement!.addEventListener(
      'scroll',
      this.handleScroll,
    );
  },
  unmounted: function () {
    imageArea.removeEventListener('mousemove', this.calcPosOfBox);
    imageArea.removeEventListener('scroll', this.calcPosOfBox);
    imageArea.removeEventListener('mouseup', this.mouseUp);
    document.removeEventListener('prepare_overlay', this.prepareOverlay);
    document.removeEventListener('reset_table_areas', this.prepareDataForAreas);
    document.removeEventListener(
      'prepare_customized_areas',
      this.prepareCustomizedAreas,
    );
    document.removeEventListener(
      'enable_column_selection',
      this.enableSelectionForRow,
    );

    let image_container = $('#image_container') as HTMLElement;
    if (image_container) {
      let parentElement = image_container.parentElement;
      if (parentElement) {
        parentElement.removeEventListener('scroll', this.handleScroll);
      }
    }
  },
  setup() {
    return {};
  },
});
</script>
