<!--vbase-->
<template>
  <f-btn
    :label="$t('deleteRule')"
    class="full-width"
    @click="confirmDelete = true"
  />
  <q-dialog v-model="confirmDelete" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('msg_delete') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          appearance="cancel"
          :label="$t('cancel')"
          v-close-popup
        />
        <f-btn
          :label="$t('delete')"
          v-close-popup
          @click="deleteRules()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import axios from 'axios';
import { defineComponent, ref } from 'vue';
import helperMixin from '../mixins/helperMixin.js';
import { api, getAuthorizationToken } from 'pages/APIs';
import { useDocLockStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
import { dynamicObj } from 'src/pages/assets.js';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { notify } from 'src/components/notifications/notify';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  emits: ['autoDetectTables'],
  props: {
    docId: {
      type: String,
      required: true,
    },
    token: {
      type: String,
      default: '',
    },
  },
  components: {},
  data() {
    return {};
  },
  computed: {},
  methods: {
    async deleteRules() {
      try {
        const actionLockAcquired = await this.hasActionAcquiredLock();
        if (!actionLockAcquired) {
          return;
        }
        this.confirmDelete = false;
        let formData = new FormData();
        formData.append('doc_id', this.docId);

        this.showLoading();
        let response: any;

        let token: string = await this.getToken();
        formData.append('org_id', getOrgId());
        response = await axios.post(api.delete_table_rules, formData, {
          headers: {
            Authorization: token,
          },
        });

        this.hideLoading();
        if (response.data.success === false) {
          throw response;
        } else {
          notify.success(
            this.$t('RULES_DELETED_SUCESSFULLY'),
          );
          const event = new CustomEvent('rules_deleted', {});
          document.dispatchEvent(event);
          this.$emit('autoDetectTables');
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async getToken() {
      let token: string =
        this.token && this.token != null && this.token != ''
          ? this.token
          : await getAuthorizationToken();
      return token;
    },
  },
  setup() {
    const doc_lock_store = useDocLockStore();
    const { hasActionAcquiredLock } = doc_lock_store;

    return {
      confirmDelete: ref(false),
      hasActionAcquiredLock,
    };
  },
});
</script>

