<template>
  <span class="ai_indicator_header">
    <span class="text">
      {{ $t('ai_indicator') }}
    </span>
  </span>
  <div id="speedometer">
    <span class="barometer"></span>
    <span class="needle"></span>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';

export default defineComponent({
  el: '#app',
  mixins: [],
  props: {},
  components: {},
  data() {
    return {
      gauge_data: {} as HTMLElement | null,
      needle: {} as HTMLElement | null,
      prop: null as any,
    };
  },
  mounted: function () {
    document.addEventListener('TE_gauge_calculation', this.TEGaugeCalculation);
    document.addEventListener('FV_gauge_calculation', this.FVGaugeCalculation);
    this.initGauge();
  },
  unmounted: function () {
    document.removeEventListener(
      'TE_gauge_calculation',
      this.TEGaugeCalculation,
    );
    document.removeEventListener(
      'FV_gauge_calculation',
      this.FVGaugeCalculation,
    );
  },
  watch: {},
  methods: {
    initGauge() {
      this.value = 0;
      this.renderGauge();
    },
    TEGaugeCalculation(e: any) {
      if (
        !e ||
        !e.detail ||
        !e.detail.hasOwnProperty('min_table_effective_weight') ||
        e.detail.min_table_effective_weight === this.value
      ) {
        return;
      }
      this.value = e.detail.min_table_effective_weight;
      this.renderGauge();
      return;
    },
    FVGaugeCalculation(e: any) {
      if (
        !e ||
        !e.detail ||
        !e.detail.hasOwnProperty('mean_effective_weight') ||
        e.detail.mean_effective_weight === this.value
      ) {
        return;
      }
      this.value = e.detail.mean_effective_weight;
      this.renderGauge();
      return;
    },
    renderGauge() {
      const turns = this.makeWithInRange(this.value);
      this.needle = document.querySelector('.needle');
      this.needle!.style.transform = 'rotate(' + turns + 'deg)';
    },
    makeWithInRange(Input: number) {
      let InputHigh = 10;
      let InputLow = 0;

      let OutputHigh = 0;
      let OutputLow = 0;

      if (Input == 5) {
        return 1;
      }
      if (Input > 5) {
        OutputHigh = 89;
        OutputLow = 1;
      }

      if (Input < 5) {
        OutputHigh = 357;
        OutputLow = 272;
      }
      return (
        ((Input - InputLow) / (InputHigh - InputLow)) *
          (OutputHigh - OutputLow) +
        OutputLow
      );
    },
    getRandomInt(min: number, max: number) {
      // his.value = this.getRandomInt(0.1,6);
      min = Math.ceil(min);
      max = Math.floor(max);
      return Math.floor(Math.random() * (max - min) + min); //The maximum is exclusive and the minimum is inclusive
    },
  },
  setup() {
    return {
      value: ref(0),
    };
  },
});
</script>

